window.PREGUNTAS = [{"id":1,"q":"¿En qué se constituye España según la Constitución?","o":["En un Estado federal y democrático.","En un Estado social y democrático de Derecho.","En una monarquía absolutista.","En un Estado centralizado."],"a":1},{"id":2,"q":"¿Cuáles son los valores superiores del ordenamiento jurídico según la Constitución?","o":["Libertad, justicia, igualdad y pluralismo político.","Igualdad, pluralismo político, seguridad y justicia.","Democracia, igualdad, legalidad y libertad.","Justicia, solidaridad, igualdad y legalidad."],"a":0},{"id":3,"q":"La forma política del Estado, según el artículo 1.3 de la Constitución, es:","o":["La república democrática.","El Estado autonómico.","La monarquía parlamentaria.","La monarquía constitucional."],"a":2},{"id":4,"q":"¿De dónde emanan los poderes del Estado según la Constitución?","o":["De la Constitución.","Del Rey.","Del Gobierno.","Del pueblo español."],"a":3},{"id":5,"q":"La Constitución reconoce y garantiza:","o":["El derecho de secesión de las nacionalidades.","La autonomía de las nacionalidades y regiones que integran la Nación española.","La independencia de las comunidades autónomas.","La centralización administrativa del Estado."],"a":1},{"id":6,"q":"Según la Constitución, los partidos políticos:","o":["Sustituyen al Parlamento.","Expresan el pluralismo político.","Dirigen el poder judicial.","Dependen del Gobierno."],"a":1},{"id":7,"q":"Según la Constitución, señale la respuesta correcta respecto a los sindicatos de trabajadores y las asociaciones empresariales:","o":["Contribuyen a la defensa y promoción de los intereses económicos y sociales que les son propios.","Su creación debe ser autorizado por el Gobierno.","El ejercicio de su actividad será controlado por el Senado.","Su estructura interna y funcionamiento podrán ser democráticos."],"a":0},{"id":8,"q":"Según la Constitución, los ciudadanos y los poderes públicos:","o":["Están sujetos a la Constitución y al resto del ordenamiento jurídico, salvo las leyes orgánicas.","Están sujetos a la Constitución y al resto del ordenamiento jurídico, salvo las leyes y los reglamentos.","Están sujetos a la Constitución y al resto del ordenamiento jurídico, salvo los reglamentos.","Están sujetos a la Constitución y al resto del ordenamiento jurídico."],"a":3},{"id":9,"q":"La Constitución garantiza:","o":["La arbitrariedad de los poderes públicos.","La retroactividad de las normas sancionadoras no favorables o restrictivas de derechos individuales.","La seguridad jurídica.","El poder absoluto del Estado."],"a":2},{"id":10,"q":"La Constitución garantiza:","o":["El principio de legalidad.","La horizontalidad normativa.","La irretroactividad de las disposiciones sancionadoras favorables.","La confidencialidad de las normas."],"a":0},{"id":11,"q":"Según la Constitución, ¿cómo se interpretarán las normas relativas a los derechos fundamentales y a las libertades que la Constitución reconoce?","o":["De conformidad con la jurisprudencia del Tribunal Supremo.","De conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España.","Únicamente según el criterio del Tribunal Constitucional.","Según lo que dictaminen las Leyes Orgánicas que los desarrollen."],"a":1},{"id":12,"q":"Según la Constitución la mayoría de edad se adquiere:","o":["A los dieciséis años.","A los dieciocho años.","A los veintiún años.","Cuando lo determine el Código Civil para cada caso concreto."],"a":1},{"id":13,"q":"Según la Constitución, los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de:","o":["Nacimiento, raza, sexo, religión o lengua.","Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.","Nacionalidad, raza, sexo, religión u opinión política.","Origen étnico, sexo, religión, convicciones o edad."],"a":1},{"id":14,"q":"Según la Constitución, todos tienen derecho a la vida y a la integridad física y moral, sin que, en ningún caso, puedan ser sometidos a:","o":["Penas de prisión superiores a treinta años.","Pruebas biológicas.","Trabajos forzados o esclavitud moderna.","Tortura ni a penas o tratos inhumanos o degradantes."],"a":3},{"id":15,"q":"Según la Constitución, ¿qué establece el artículo 16.3 respecto a la confesión del Estado?","o":["Ninguna confesión tendrá carácter estatal.","El Estado es católico por tradición histórica.","El Estado cooperará únicamente con la Iglesia Católica.","Los poderes públicos no tendrán en cuenta las creencias religiosas de la sociedad."],"a":0},{"id":16,"q":"Según la Constitución, la detención preventiva NO podrá durar más del tiempo estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, en el plazo máximo de:","o":["Veinticuatro horas.","Cuarenta y ocho horas.","Setenta y dos horas.","Cinco días naturales."],"a":2},{"id":17,"q":"Según la Constitución, ¿en qué casos se puede entrar o registrar un domicilio sin el consentimiento del titular?","o":["Por orden de la autoridad gubernativa o en caso de urgencia.","En caso de flagrante delito o resolución judicial.","Siempre que exista una investigación policial en curso.","Solo mediante resolución judicial firme."],"a":1},{"id":18,"q":"Según la Constitución, ¿en qué supuesto se podrá acordar el secuestro de publicaciones, grabaciones y otros medios de información?","o":["Por decisión del Ministerio del Interior.","Mediante resolución administrativa motivada.","En virtud de resolución judicial.","Cuando atenten contra la moral pública."],"a":2},{"id":19,"q":"Según la Constitución, en los casos de reuniones en lugares de tránsito público y manifestaciones, se dará comunicación previa a la autoridad, que sólo podrá prohibirlas cuando:","o":["Existan razones fundadas de alteración del orden público, con peligro para personas o bienes.","El número de asistentes sea superior a 100 personas.","Coincidan con un periodo de campaña electoral.","Entorpezcan gravemente la circulación de vehículos."],"a":0},{"id":20,"q":"Según la Constitución, las asociaciones que persigan fines o utilicen medios tipificados como delito son:","o":["Sancionables administrativamente.","Ilegales.","Legales, aunque nulas de pleno derecho.","Suspendibles por el Ministerio del Interior."],"a":1},{"id":21,"q":"Según la Constitución, los ciudadanos tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen:","o":["Los reglamentos de las Cámaras.","Los Gobiernos autonómicos y locales.","Las autoridades judiciales.","Las leyes."],"a":3},{"id":22,"q":"Según la Constitución, las penas privativas de libertad y las medidas de seguridad estarán orientadas hacia:","o":["El castigo ejemplarizante y la retribución.","El aislamiento del delincuente de la sociedad.","La reparación del daño a la víctima.","La reeducación y reinserción social."],"a":3},{"id":23,"q":"Según la Constitución, la enseñanza básica es:","o":["Obligatoria y gratuita.","Gratuita hasta los doce años.","Obligatoria hasta los catorce años.","Obligatoria, gratuita y católica."],"a":0},{"id":24,"q":"Según la Constitución, se reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses. La ley que regule el ejercicio de este derecho establecerá las garantías precisas para asegurar:","o":["El derecho al trabajo de los no huelguistas.","El mantenimiento de los servicios esenciales de la comunidad.","La seguridad de las instalaciones productivas.","El pago de los salarios durante el conflicto."],"a":1},{"id":25,"q":"Según la Constitución, todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de:","o":["Igualdad y proporcionalidad.","Igualdad y progresividad.","Solidaridad y eficiencia.","Equidad y suficiencia."],"a":1},{"id":26,"q":"Según la Constitución, nadie podrá ser privado de sus bienes y derechos:","o":["Sino por causa justificada de utilidad pública o interés social mediante la correspondiente indemnización y de conformidad con lo dispuesto por las leyes.","Salvo los bienes y derechos adquiridos mediante herencia.","Salvo las personas mayores de 50 años sin menores dependientes.","En ningún caso."],"a":0},{"id":27,"q":"Según la Constitución, los padres deben prestar asistencia de todo orden a los hijos habidos dentro o fuera del matrimonio:","o":["Hasta que alcancen la mayoría de edad.","Mientras convivan en el domicilio familiar.","Hasta que finalicen sus estudios superiores.","Durante su minoría de edad y en los demás casos en que legalmente proceda."],"a":3},{"id":28,"q":"Según la Constitución, ¿qué aspecto deben garantizar los poderes públicos mediante la limitación de la jornada laboral y las vacaciones periódicas retribuidas?","o":["El derecho a la conciliación familiar y laboral.","El incremento de la productividad nacional.","El descanso necesario.","La reducción de los accidentes de trabajo."],"a":2},{"id":29,"q":"Según la Constitución, se reconoce el derecho a la protección de la salud. Compete a los poderes públicos organizar y tutelar la salud pública a través de:","o":["La creación de hospitales públicos en cada municipio.","El control de precios de los medicamentos.","Medidas preventivas y de las prestaciones y servicios necesarios.","La gestión directa de todos los centros sanitarios."],"a":2},{"id":30,"q":"Según la Constitución, todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como:","o":["El deber de conservarlo.","El deber de denunciar a los infractores.","El derecho a recibir indemnizaciones por contaminación.","El deber de reciclar los residuos domésticos."],"a":0},{"id":31,"q":"Las Cortes Generales están formadas por:","o":["El Congreso de los Diputados, el Gobierno y el Tribunal Constitucional.","El Congreso de los Diputados, el Senado y el Consejo General del Poder Judicial.","El Congreso de los Diputados y el Gobierno.","El Congreso de los Diputados y el Senado."],"a":3},{"id":32,"q":"Ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno y tienen las demás competencias que les atribuya la Constitución:","o":["Las Cortes Generales.","El Tribunal Constitucional y el Tribunal Supremo.","Los partidos políticos de la oposición.","Las Cortes Generales y el Tribunal Constitucional."],"a":0},{"id":33,"q":"Señale la respuesta correcta sobre el Congreso:","o":["Se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto, en los términos que establezca la ley.","Es la Cámara de representación territorial.","La circunscripción electoral es la comunidad autónoma.","Es elegido por cinco años."],"a":0},{"id":34,"q":"Señale la respuesta correcta sobre el Senado:","o":["Se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto, en los términos que establezca la ley.","Es la Cámara de representación territorial.","La circunscripción electoral es la comunidad autónoma.","Es elegido por cinco años."],"a":1},{"id":35,"q":"Según la Constitución, son leyes orgánicas:","o":["Las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las que regulan el procedimiento administrativo común y el régimen electoral general y las demás previstas en la Constitución.","Las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las que aprueben los Estatutos de Autonomía y el régimen electoral general y las demás previstas en la Constitución.","Las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las que aprueben los Estatutos de Autonomía y el régimen electoral general, las relativas a cuestiones medio ambientales y las demás previstas en la Constitución.","Las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las relativas a cuestiones medioambientales y las demás previstas en la Constitución."],"a":1},{"id":36,"q":"La aprobación, modificación o derogación de las leyes orgánicas:","o":["Exigirá mayoría simple del Congreso, en una votación final sobre el conjunto del proyecto.","Exigirá mayoría simple del Senado, en una votación final sobre el conjunto del proyecto.","Exigirá mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.","Exigirá mayoría absoluta del Senado, en una votación final sobre el conjunto del proyecto."],"a":2},{"id":37,"q":"Las Cortes Generales:","o":["Podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas no incluidas en el artículo 81 que recibirán el título de Decretos Legislativos.","Podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas no incluidas en el artículo 81 que recibirán el título de Decretos-Leyes.","Podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre cualquier materia que recibirán el título de Decretos Legislativos.","Podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre cualquier materia que recibirán el título de Decretos-Leyes."],"a":0},{"id":38,"q":"Según la Constitución Española, en caso de extraordinaria y urgente necesidad, el Gobierno podrá dictar disposiciones legislativas provisionales que:","o":["Tomarán la forma de Decretos Legislativos y que no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I de la Constitución, al régimen de las Comunidades Autónomas ni al Derecho electoral general.","Tomarán la forma de Decretos Legislativos y que podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I de la Constitución, al régimen de las Comunidades Autónomas y al Derecho electoral general.","Tomarán la forma de Decretos-leyes y que podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I de la Constitución, al régimen de las Comunidades Autónomas y al Derecho electoral general.","Tomarán la forma de Decretos-leyes y que no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades de los ciudadanos regulados en el Título I de la Constitución, al régimen de las Comunidades Autónomas ni al Derecho electoral general."],"a":3},{"id":39,"q":"Señale la respuesta INCORRECTA respecto a la iniciativa legislativa:","o":["La iniciativa legislativa corresponde al Gobierno, al Congreso y al Senado, de acuerdo con la Constitución y los Reglamentos de las Cámaras.","Las Asambleas de las Comunidades Autónomas podrán solicitar del Gobierno la adopción de un proyecto de ley o remitir a la Mesa del Congreso una proposición de ley, delegando ante dicha Cámara un máximo de tres miembros de la Asamblea encargados de su defensa.","Una ley orgánica regulará las formas de ejercicio y requisitos de la iniciativa popular para la presentación de proposiciones de ley. En todo caso se exigirán no menos de 500.000 firmas acreditadas.","La iniciativa popular procederá únicamente en materias propias de ley orgánica, tributarias o de carácter internacional."],"a":3},{"id":40,"q":"Aprobado un proyecto de ley ordinaria u orgánica por el Congreso de los Diputados:","o":["Su Presidente dará inmediata cuenta del mismo al Presidente del Senado, el cual lo someterá a la deliberación de éste.","El Rey la sancionará y promulgará en el plazo de quince días y ordenará su inmediata publicación.","Su Presidente dará inmediata cuenta del mismo al Presidente del Gobierno, el cual ordenará su publicación inmediata.","Su Presidente dará inmediata cuenta del mismo al Consejo de Ministros, que deberá iniciar los trámites para su aprobación por el Senado."],"a":0},{"id":41,"q":"Según la Constitución, se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución internacional el ejercicio de competencias derivadas de la Constitución:","o":["Mediante ley.","Mediante ley orgánica.","Mediante ley de bases.","Mediante ley marco."],"a":1},{"id":42,"q":"Según la Constitución, la prestación del consentimiento del Estado para obligarse por medio de tratados políticos requerirá la previa autorización de:","o":["El Gobierno.","El Congreso.","El Senado.","Las Cortes Generales."],"a":3},{"id":43,"q":"Según la Constitución, el Gobierno:","o":["Ejerce la función legislativa y la potestad reglamentaria de acuerdo con la Constitución y las leyes.","Ejerce la función legislativa y ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.","Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.","Ejerce la función ejecutiva y delega la potestad reglamentaria a las Cortes Generales de acuerdo con la Constitución y las leyes."],"a":2},{"id":44,"q":"Según la Constitución, el Gobierno se compone de:","o":["El Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley.","El Presidente, de los Vicepresidentes, en su caso, de los Ministros, que no podrán ser más de ocho y de los demás miembros que establezca la ley.","El Presidente, de los Vicepresidentes, en su caso, de los Ministros, que no podrán ser más de diez y de los demás miembros que establezca la ley.","El Presidente, cinco diputados y cinco senadores nombrados por el Presidente."],"a":0},{"id":45,"q":"Según la Constitución, después de cada renovación del Congreso de los Diputados, el Rey, previa consulta con los representantes designados por los grupos políticos con representación parlamentaria, y a través del Presidente del Congreso, propondrá un candidato a:","o":["La Presidencia de las Cortes.","La Presidencia del Gobierno.","La Jefatura del Estado.","El Consejo de Ministros."],"a":1},{"id":46,"q":"Según la Constitución, los demás miembros del Gobierno serán nombrados y separados por el Rey, a propuesta de:","o":["Las Cortes Generales.","El Presidente del Gobierno.","El Consejo de Estado.","Los partidos de la oposición."],"a":1},{"id":47,"q":"Según la Constitución, el Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por:","o":["Disolución de las Cortes Generales por el Rey.","Dimisión o fallecimiento de su Presidente.","Dimisión o fallecimiento de la mayoría de sus miembros.","Petición de tres quintos del Senado."],"a":1},{"id":48,"q":"Según la Constitución, la Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de:","o":["Eficiencia, jerarquía, centralización, concentración y coordinación.","Eficiencia, horizontalidad, descentralización, desconcentración y coordinación.","Eficacia, jerarquía, centralización, concentración y coordinación.","Eficacia, jerarquía, descentralización, desconcentración y coordinación."],"a":3},{"id":49,"q":"La ley regulará el estatuto de los funcionarios públicos, el acceso a la función pública de acuerdo con los principios de:","o":["Capacidad y antigüedad.","Mérito y antigüedad.","Mérito y capacidad.","Capacidad, mérito y antigüedad."],"a":2},{"id":50,"q":"Según la Constitución, la ley regulará la audiencia de los ciudadanos, directamente o a través de las organizaciones y asociaciones reconocidas por la ley, en el procedimiento de elaboración de:","o":["Las disposiciones administrativas que les afecten.","Las Leyes Orgánicas.","Los Tratados Internacionales.","Los Presupuestos Generales del Estado."],"a":0},{"id":51,"q":"Los particulares, en los términos establecidos por la ley, tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos, salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia de:","o":["El funcionamiento de los servicios públicos.","Una negligencia grave de la autoridad judicial.","Una ley declarada inconstitucional.","La actuación de las Fuerzas y Cuerpos de Seguridad."],"a":0},{"id":52,"q":"El Consejo de Estado es el supremo órgano consultivo del:","o":["Rey.","Congreso de los Diputados.","Gobierno.","Tribunal Supremo."],"a":2},{"id":53,"q":"Según la Constitución, el Gobierno responde solidariamente en su gestión política ante:","o":["El Rey.","El Congreso de los Diputados.","Las Cortes Generales.","El Tribunal Supremo."],"a":1},{"id":54,"q":"El Presidente del Gobierno, previa deliberación del Consejo de Ministros, puede plantear ante el Congreso de los Diputados la cuestión de confianza sobre su programa o sobre una declaración de política general. La confianza se entenderá otorgada cuando vote a favor de la misma:","o":["La mayoría absoluta de los Diputados.","La mayoría simple de los Diputados.","La mayoría absoluta de las Cortes Generales.","La mayoría simple de las Cortes Generales."],"a":1},{"id":55,"q":"Según la Constitución, la moción de censura deberá ser propuesta, al menos, por:","o":["La décima parte de los Diputados.","La cuarta parte de los Diputados.","La mayoría simple del Congreso.","Cincuenta Diputados o cincuenta Senadores."],"a":0},{"id":56,"q":"El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva de:","o":["El Rey.","El Consejo de Defensa Nacional.","Dos tercios de los miembros del Senado.","El Gobierno."],"a":3},{"id":57,"q":"Según la Constitución, la justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, que son:","o":["Independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.","Elegidos por sufragio universal y secreto.","Nombrados por el Gobierno a propuesta del Consejo General del Poder Judicial.","Elegidos entre los miembros de las Cortes Generales."],"a":0},{"id":58,"q":"La justicia será gratuita cuando así lo disponga la ley y, en todo caso, respecto de quienes:","o":["Se encuentren en situación de desempleo.","Sean menores de edad o personas con discapacidad.","Acrediten insuficiencia de recursos para litigar.","Sean víctimas de violencia machista."],"a":2},{"id":59,"q":"Los daños causados por error judicial, así como los que sean consecuencia del funcionamiento anormal de la Administración de Justicia, darán derecho a:","o":["Una disculpa pública del Ministerio de Justicia.","La anulación inmediata de todas las causas pendientes del afectado.","Una indemnización a cargo del Estado, conforme a la ley.","Una sanción disciplinaria para el Juez responsable."],"a":2},{"id":60,"q":"Señale la respuesta correcta respecto al Consejo General del Poder Judicial:","o":["Es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales.","El Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte miembros nombrados por el Rey por un período de cinco años.","Cuatro de los miembros serán nombrados a propuesta del Congreso de los Diputados, y otros cuatro a propuesta del Senado, elegidos en ambos casos por mayoría absoluta de sus miembros, entre abogados y otros juristas, todos ellos de reconocida competencia y con más de diez años de ejercicio en su profesión.","El Consejo General del Poder Judicial, sin perjuicio de las funciones encomendadas a otros órganos, tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de los Tribunales y procurar ante éstos la satisfacción del interés social."],"a":1},{"id":61,"q":"El Estado se organiza territorialmente en:","o":["Municipios, en provincias y en las Comunidades Autónomas que se constituyan.","Municipios, Comarcas y en las Comunidades Autónomas que se constituyan.","Ayuntamientos, Diputaciones y Gobiernos Regionales.","Municipios y en cuatro áreas regionales."],"a":0},{"id":62,"q":"Según la Constitución, señale la respuesta correcta:","o":["Los Concejales serán elegidos por el Alcalde.","Los Alcaldes y Concejales serán elegidos por las Cortes Generales.","Los Alcaldes serán elegidos por los Concejales o por los vecinos.","Los Alcaldes serán elegidos por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto, en la forma establecida por la ley."],"a":2},{"id":63,"q":"La provincia es una entidad local con personalidad jurídica propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado. Cualquier alteración de los límites provinciales habrá de ser aprobada:","o":["Por las Cortes Generales mediante ley ordinaria.","Por el Senado mediante ley ordinaria.","Por las Cortes Generales mediante ley orgánica.","Por el Senado mediante ley orgánica."],"a":2},{"id":64,"q":"Las Haciendas locales deberán disponer de los medios suficientes para el desempeño de las funciones que la ley atribuye a las Corporaciones respectivas y se nutrirán fundamentalmente de:","o":["Subvenciones estatales y fondos europeos de desarrollo.","Tributos propios y de participación en los del Estado y de las Comunidades Autónomas.","Donaciones privadas y tasas por servicios municipales.","Préstamos bancarios avalados por el Tesoro Público."],"a":1},{"id":65,"q":"Según la Constitución, las Comunidades Autónomas podrán asumir competencias en materias como:","o":["Relaciones internacionales.","Legislación sobre propiedad intelectual e industrial.","Régimen de producción, comercio, tenencia y uso de armas y explosivos.","Los montes y aprovechamientos forestales."],"a":3},{"id":66,"q":"Según la Constitución, el Estado tiene competencia exclusiva sobre la siguiente materia:","o":["La artesanía.","Administración de Justicia.","Asistencia social.","Promoción del deporte y del ocio."],"a":1},{"id":67,"q":"Señale la respuesta correcta:","o":["Las Cortes Generales, en materias de competencia estatal, podrán atribuir a todas o a alguna de las Comunidades Autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, bases y directrices fijados por una ley estatal.","El Estado podrá transferir o delegar en las Comunidades Autónomas, mediante ley ordinaria, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.","El Estado podrá dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las Comunidades Autónomas, aun en el caso de materias atribuidas a la competencia de éstas, cuando así lo exija el interés general. Corresponde a las Cortes Generales, por mayoría simple de cada Cámara, la apreciación de esta necesidad.","Las materias no atribuidas expresamente al Estado por esta Constitución corresponderán a las Comunidades Autónomas."],"a":0},{"id":68,"q":"Según la Constitución Española, la organización institucional autonómica se basará en una Asamblea Legislativa elegida por:","o":["Sufragio universal, con arreglo a un sistema de representación proporcional.","Designación directa de los Ayuntamientos.","Designación directa de las Diputaciones.","Designación directa del Senado."],"a":0},{"id":69,"q":"¿Quién ejerce el control de la administración autónoma y sus normas reglamentarias según la Constitución?","o":["El Tribunal Constitucional.","El Gobierno, previo dictamen del Consejo de Estado.","La jurisdicción contencioso-administrativa.","El Tribunal de Cuentas."],"a":2},{"id":70,"q":"Según la Constitución, ¿quién nombra al Delegado que dirigirá la administración del Estado en el territorio de la Comunidad Autónoma?","o":["El Rey.","El Gobierno.","El Presidente de la Comunidad Autónoma.","El Congreso de los Diputados."],"a":1},{"id":71,"q":"¿Qué es el Estatuto de Autonomía para el País Vasco?","o":["Es un convenio firmado entre el Gobierno Vasco y el Gobierno de España.","Es la norma que sustituye a la Constitución Española en el País Vasco.","Es un acuerdo entre el Parlamento Vasco y las Cortes Generales que debe ser revisada cada cuatro años.","Es la norma institucional básica de la Comunidad Autónoma del País Vasco."],"a":3},{"id":72,"q":"Según el Estatuto de Autonomía para el País Vasco, el euskera es:","o":["Lengua cooficial en zonas urbanas y única lengua oficial en zonas rurales.","Lengua propia del Pueblo Vasco.","Lengua oficial únicamente en el ámbito administrativo.","Lengua oficial únicamente en el ámbito cultural."],"a":1},{"id":73,"q":"Según el Estatuto de Autonomía para el País Vasco, los poderes públicos vascos, en el ámbito de su competencia:","o":["Velarán y garantizarán el adecuado ejercicio de los derechos y deberes fundamentales de los ciudadanos.","Impulsarán una política tendente al mantenimiento de las condiciones de vida y trabajo actuales.","Adoptarán aquellas medidas que tiendan a fomentar la productividad económica.","Facilitarán la participación de todos los ciudadanos en la vida económica, cultural y social del País Vasco y la limitarán en la vida política."],"a":0},{"id":74,"q":"Según el Estatuto de Autonomía para el País Vasco, ¿dónde están establecidos los derechos y deberes fundamentales de los ciudadanos del País Vasco?","o":["En la Constitución.","En el Estatuto de Autonomía.","En la Ley de derechos fundamentales del País Vasco.","En cada una de las normas forales de organización de los Territorios Históricos."],"a":0},{"id":75,"q":"Según el Estatuto de Autonomía para el País Vasco, ¿en qué materia tiene competencia exclusiva la Comunidad Autónoma del País Vasco?","o":["Medio ambiente y ecología.","Ordenación del crédito, banca y seguros.","Asistencia social.","Régimen minero y energético."],"a":2},{"id":76,"q":"Según el Estatuto de Autonomía para el País Vasco, ¿en cuál de las siguientes materias le corresponde a la Comunidad Autónoma del País Vasco la ejecución de la legislación del Estado?","o":["Ordenación del territorio y del litoral, urbanismo y vivienda.","Turismo y deporte.","Propiedad intelectual e industrial.","Espectáculos."],"a":2},{"id":77,"q":"Señale la respuesta correcta. La competencia de los órganos jurisdiccionales en el País Vasco se extiende:","o":["En el orden civil, a todas las instancias y grados, con excepción de los recursos de casación y de revisión.","En el orden penal y social, a todas las instancias y grados, con excepción de los recursos de casación y de revisión.","En el orden contencioso-administrativo, a todas las instancias y grados cuando se trate de actos dictados por la Administración del Estado, y, en primera instancia, cuando se trate de actos dictados por la Administración del País Vasco.","A las cuestiones de competencia entre órganos judiciales del País Vasco y de las comunidades autónomas limítrofes."],"a":1},{"id":78,"q":"Según el Estatuto de Autonomía para el País Vasco, ¿qué le corresponderá al País Vasco en materia de Seguridad Social?","o":["El desarrollo legislativo y la ejecución de la legislación básica del Estado, incluso las normas que configuran el régimen económico de la misma.","El desarrollo legislativo y la ejecución de las normas que configuran el régimen económico de la Seguridad Social.","El desarrollo legislativo y la ejecución de la legislación básica del Estado, salvo las normas que configuran el régimen económico de la misma.","La ejecución de la legislación del Estado."],"a":2},{"id":79,"q":"Según el Estatuto de Autonomía para el País Vasco, señale la respuesta correcta entre las siguientes opciones:","o":["La Comunidad Autónoma podrá celebrar convenios con otras Comunidades Autónomas para la gestión y prestación de servicios propios de la exclusiva competencia de las mismas. La celebración de los citados convenios, antes de su entrada en vigor, deberá ser comunicada a las Cortes Generales.","La Comunidad Autónoma podrá celebrar convenios con otras Comunidades Autónomas para la gestión y prestación de servicios propios de la exclusiva competencia de las mismas. La celebración de los citados convenios, después de su entrada en vigor, deberá ser comunicada a las Cortes Generales.","La Comunidad Autónoma podrá celebrar convenios con otras Comunidades Autónomas para la gestión y prestación de servicios propios de la exclusiva competencia de las mismas. La celebración de los citados convenios, antes de su entrada en vigor, deberá ser comunicada al Gobierno de España.","La Comunidad Autónoma no podrá celebrar convenios con otras Comunidades Autónomas para la gestión y prestación de servicios propios de la exclusiva competencia de las mismas."],"a":0},{"id":80,"q":"Según el Estatuto de Autonomía del País Vasco, los poderes del País Vasco se ejercerán a través:","o":["Del Parlamento, del Gobierno y de su Presidente o Lendakari.","Del Parlamento, y del Gobierno.","Del Parlamento, y del Presidente o Lendakari.","Del Parlamento."],"a":0},{"id":81,"q":"Según el Estatuto de Autonomía del País Vasco, el Parlamento Vasco:","o":["Ejerce la potestad ejecutiva, aprueba sus presupuestos e impulsa y controla la acción del Gobierno Vasco.","Ejerce la potestad ejecutiva, aprueba sus presupuestos e impulsa y controla la acción del Gobierno Vasco y las diputaciones forales.","Ejerce la potestad legislativa, aprueba sus presupuestos e impulsa y controla la acción del Gobierno Vasco.","Ejerce la potestad legislativa, aprueba sus presupuestos e impulsa y controla la acción del Gobierno Vasco y las diputaciones forales."],"a":2},{"id":82,"q":"Según el Estatuto de Autonomía para el País Vasco, señale la respuesta correcta sobre el Parlamento Vasco:","o":["Estará integrado por un número igual de representantes de cada Territorio Histórico elegidos por sufragio universal, libre, directo y secreto, la circunscripción electoral es el Territorio Histórico y será elegido por un período de cuatro años.","Estará integrado por un número proporcional de representantes de cada Territorio Histórico en función del número de habitantes, elegidos por sufragio universal, libre, directo y secreto, la circunscripción electoral es el Territorio Histórico y será elegido por un período de cuatro años.","Estará integrado por un número igual de representantes de cada circunscripción electoral elegidos por sufragio universal, libre, directo y secreto, la circunscripción electoral son las comarcas de cada territorio histórico y será elegido por un período de cuatro años.","Estará integrado por un número igual de representantes de cada Territorio Histórico elegidos por sufragio universal, libre, directo y secreto, la circunscripción electoral es el Territorio Histórico y será elegido por un período de cinco años."],"a":0},{"id":83,"q":"Según el Estatuto de Autonomía del País Vasco, ¿qué órgano colegiado ostenta las funciones ejecutivas y administrativas del País Vasco?","o":["El Parlamento Vasco.","El Gobierno Vasco.","El Departamento de Lehendakaritza.","La comisión ejecutiva del Parlamento Vasco."],"a":1},{"id":84,"q":"Según el Estatuto de Autonomía para el País Vasco, señale la respuesta correcta:","o":["El Gobierno Vasco cesa tras la celebración de elecciones del Parlamento, en el caso de pérdida de la confianza parlamentaria o por dimisión o fallecimiento de su Presidente o Consejeros.","El Gobierno cesante continuará en funciones hasta la celebración de nuevas elecciones.","El Presidente del Gobierno Vasco será designado de entre sus miembros por el Parlamento Vasco y nombrado por el Presidente del Gobierno de España.","El Presidente designa y separa los Consejeros del Gobierno, dirige su acción, ostentando a la vez la más alta representación del País Vasco y la ordinaria del Estado en este territorio."],"a":3},{"id":85,"q":"Los conflictos de competencia que se puedan suscitar entre las Instituciones de la Comunidad Autónoma y las de cada uno de sus Territorios Históricos se someterán a la decisión de:","o":["Una comisión arbitral, formada por un número igual de representantes designados libremente por el Gobierno Vasco y por la Diputación Foral del Territorio interesado, y presidida por el Presidente del Tribunal Superior de Justicia del País Vasco.","Una comisión arbitral, formada por un número igual de representantes designados libremente por el Gobierno Vasco y por la Diputación Foral del Territorio interesado, y presidida por el Presidente del Tribunal Supremo.","El Senado.","El Parlamento Vasco."],"a":0},{"id":86,"q":"De acuerdo con su tradición histórica, son Instituciones y Órganos Forales del Territorio Histórico de Gipuzkoa:","o":["Las Juntas Generales.","La Diputación Foral y los Ayuntamientos de Gipuzkoa.","Las Juntas Generales y la Diputación Foral.","Las Juntas Generales, la Diputación Foral y los Ayuntamientos de Gipuzkoa."],"a":2},{"id":87,"q":"Señale la respuesta correcta. Según la Norma Foral 6/2005:","o":["Las Juntas Generales, que constituyen el Órgano máximo de representación y participación popular del Territorio Histórico, son el Parlamento de Gipuzkoa.","Las Juntas Generales están compuestos por el Diputado General o la Diputada General y los Diputados Forales o las Diputadas Forales.","A efectos de elección a las Juntas Generales, la única circunscripción electoral es el Territorio Histórico de Gipuzkoa.","Las Juntas Generales ejercen la potestad normativa en los términos establecidos en la presente Norma Foral, evalúan los resultados de dicha potestad, eligen a los Diputados Forales o a las Diputadas Forales, aprueban sus presupuestos y, a iniciativa de la Diputación Foral, los del Territorio Histórico, y controlan la acción de aquélla."],"a":0},{"id":88,"q":"Las disposiciones emanadas de las Juntas Generales en virtud de su potestad normativa se denominan:","o":["Leyes Orgánicas Forales.","Normas Forales.","Decretos Forales.","Ordenes Forales."],"a":1},{"id":89,"q":"Según la Norma Foral 6/2005, las Normas Forales:","o":["Serán publicadas en el Boletín Oficial de Gipuzkoa y en el Boletín Oficial del País Vasco y entrarán en vigor a los 10 días de su publicación en aquel, salvo disposición en contrario.","Las Normas Forales serán publicadas en el Boletín Oficial de Gipuzkoa, en el Boletín Oficial del País Vasco y en el Boletín Oficial del Estado y entrarán en vigor a los 10 días de su publicación en aquel, salvo disposición en contrario.","Las Normas Forales serán publicadas en el Boletín Oficial de Gipuzkoa y en el Boletín Oficial del País Vasco y entrarán en vigor a los 20 días de su publicación en aquel, salvo disposición en contrario.","Las Normas Forales serán publicadas en el Boletín Oficial de Gipuzkoa, en el Boletín Oficial del País Vasco y en el Boletín Oficial del Estado y entrarán en vigor a los 20 días de su publicación en aquel, salvo disposición en contrario."],"a":2},{"id":90,"q":"Según la Norma Foral 6/2005, se regularán mediante Norma Foral:","o":["Los Presupuestos del Territorio Histórico y sus cuentas generales.","Las áreas de actuación y funciones de los Departamentos Forales.","Los planes territoriales, planes urbanísticos supramunicipales y el planeamiento general urbanístico municipal.","Los planes de empleo y la oferta de empleo público de la Diputación Foral."],"a":0},{"id":91,"q":"Según la Norma Foral 6/2005, señale la respuesta correcta respecto a las Juntas Generales:","o":["Las Juntas Generales de Gipuzkoa se regirán en cuanto a su constitución, organización y funcionamiento por lo dispuesto en su Reglamento.","La Juntas Generales elegirán de entre sus miembros un Presidente o Presidenta y una Mesa, que estará integrada por éste, dos Vicepresidencias, dos Secretarías y dos Diputados o Diputadas Forales, la cual será el órgano rector de la Cámara y ostentará la representación colegiada de ésta en los actos a que asista.","La modificación o derogación del Reglamento de Juntas Generales, así como la aprobación de uno nuevo, exigirá mayoría simple de las Juntas Generales en una votación final sobre el conjunto del proyecto.","El Reglamento de las Juntas Generales será promulgado por el o la Lehendakari, teniendo el rango y valor de una Ley."],"a":0},{"id":92,"q":"Según la Norma Foral 6/2005, las Juntas Generales podrán delegar en la Diputación Foral la potestad de dictar disposiciones normativas con rango de Norma Foral, denominadas:","o":["Norma Foral de Bases.","Decreto Foral Normativo.","Orden Foral.","Decreto Foral-Norma."],"a":1},{"id":93,"q":"Según la Norma Foral 6/2005, por razones de extraordinaria y urgente necesidad, el Consejo de Gobierno Foral podrá dictar disposiciones normativas provisionales, dentro del ámbito de sus competencias exclusivas, que tomarán la forma de:","o":["Norma Foral de Bases.","Decreto Foral Normativo.","Orden Foral.","Decreto Foral-Norma."],"a":3},{"id":94,"q":"Según la Norma Foral 6/2005, la Diputación Foral se compone:","o":["De junteros y junteras.","De la Comisión Permanente y la Junta de Portavoces.","Del Diputado o Diputada General y un número de diputadas y diputados forales que no podrá exceder de diez.","Del Diputado o Diputada General, de diputadas y diputados forales y de un número de directoras y directores generales que no podrá exceder de diez."],"a":2},{"id":95,"q":"Según la Norma Foral 6/2005, la Diputación Foral ostenta la representación legal del Territorio Histórico de Gipuzkoa y en la esfera de sus competencias, asume su gobierno y administración, correspondiéndole:","o":["Las funciones normativas.","Las funciones normativas, ejecutivas y administrativas, la potestad reglamentaria.","Las funciones ejecutivas y administrativas, la potestad reglamentaria y la iniciativa normativa.","Las funciones ejecutivas y administrativas, la potestad reglamentaria la iniciativa normativa y aprobar los presupuestos generales del Territorio Histórico."],"a":2},{"id":96,"q":"Según la Norma Foral 6/2005, señale la respuesta correcta respecto al Diputado o Diputada General:","o":["La elección del Diputado o Diputada General la realizará el Consejo de Gobierno Foral de entre sus miembros de derecho, mediante votación secreta.","Para la designación del Diputado o Diputada General será necesario que un candidato o candidata tenga, en primera votación, la mayoría simple de los votos de las y los miembros electos de las Juntas Generales.","El acuerdo de nombramiento del Diputado o Diputada General será firmado por el Presidente o Presidenta de las Juntas Generales y publicado en el Boletín Oficial de Gipuzkoa y en el Boletín Oficial del País Vasco.","El Diputado o Diputada General asume la presidencia de las Juntas Generales."],"a":2},{"id":97,"q":"Según la Norma Foral 6/2005, corresponde al Diputado o Diputada General:","o":["Aprobar los Proyectos de Norma Foral para su remisión a las Juntas Generales y determinar su retirada en las condiciones que establezca el Reglamento de las mismas.","Ejercer mediante Decretos Forales Normativos la delegación normativa en los términos establecidos en la Norma Foral 6/2005.","Resolver los recursos que se interpongan contra los actos del Consejo de Gobierno Foral.","Designar y cesar a las diputadas y diputados forales, y asignarles la titularidad de los distintos Departamentos."],"a":3},{"id":98,"q":"Según la Norma Foral 6/2005, corresponde al Consejo de Gobierno Foral:","o":["Definir el programa de gobierno y llevar su dirección.","Aprobar los Decretos Forales-Norma en los supuestos y términos establecidos en la Norma Foral 6/2005.","Nombrar, de entre las diputadas y diputados forales, un o una o varios o varias tenientes de Diputado o Diputada General.","Resolver en vía administrativa los recursos que se interpongan contra actos y resoluciones dictados por los Diputados o Diputadas Forales."],"a":1},{"id":99,"q":"Según la Norma Foral 6/2005, la celebración de las sesiones del Consejo de Gobierno Foral requerirá, para su válida Constitución:","o":["La asistencia del Diputado o Diputada General y del diputado foral secretario o diputada foral secretaria, o quienes les sustituyan, debiendo estar presentes al menos, tres de las y los miembros.","La asistencia del Diputado o Diputada General y del diputado foral secretario o diputada foral secretaria, o quienes les sustituyan, debiendo estar presentes al menos, la mitad de las y los miembros.","La asistencia del Diputado o Diputada General y del diputado foral secretario o diputada foral secretaria, o quienes les sustituyan, debiendo estar presentes al menos, dos tercios de las y los miembros.","La asistencia del Diputado o Diputada General o del diputado foral secretario o diputada foral secretaria, o quienes les sustituyan, debiendo estar presentes al menos, dos tercios de las y los miembros."],"a":1},{"id":100,"q":"Según la Norma Foral 6/2005, compete a las diputadas y diputados forales:","o":["Aprobar el nombramiento y cese de las directoras y directores generales de su Departamento.","Resolver en vía administrativa los recursos que se interpongan contra actos y resoluciones dictados por el Consejo de Gobierno Foral en las materias de su competencia.","Ejercer la iniciativa de propuesta al Consejo de Gobierno Foral sobre la estructura orgánica y funcional de su Departamento.","Aprobar los Decretos Forales en las materias propias del Departamento."],"a":2},{"id":101,"q":"Señale la respuesta correcta respecto a las directoras y directores generales según la Norma Foral 6/2005:","o":["Son altos cargos de la Diputación Foral. Su designación y cese se efectuará por Decreto Foral del Consejo de Gobierno Foral.","Son altos cargos de la Diputación Foral. Su designación y cese se efectuará por Decreto Foral del Diputado o Diputada General.","Son altos cargos de la Diputación Foral. Su designación y cese se efectuará por Orden Foral del Diputado o Diputada General.","Son altos cargos de la Diputación Foral. Su designación y cese se efectuará por Acuerdo del Consejo de Gobierno Foral."],"a":0},{"id":102,"q":"Según la Norma Foral 6/2005, los órganos superiores de la Administración Foral son:","o":["Los órganos superiores de la Administración Foral son el Consejo de Gobierno Foral, el Diputado o Diputada General, las diputadas y diputados forales y las directoras y directores generales.","Los órganos superiores de la Administración Foral son el Consejo de Gobierno Foral, el Diputado o Diputada General, y las diputadas y diputados forales.","Los órganos superiores de la Administración Foral son el Consejo de Gobierno Foral y el Diputado o Diputada General.","Los órganos superiores de la Administración Foral son el Diputado o Diputada General, y las diputadas y diputados forales."],"a":1},{"id":103,"q":"Según la Norma Foral 6/2005, señale la respuesta correcta sobre los Departamentos de la Diputación Foral de Gipuzkoa:","o":["Toda variación en el número, denominación y competencias de los Departamentos y la creación, fusión, supresión y reforma de los mismos se establecerá por Decreto Foral del Consejo de Gobierno Foral.","En cada Departamento habrá una Secretaría Técnica que tendrá atribuidas las competencias sobre servicios comunes que determine el Decreto Foral de estructura orgánica de aquel, y en todo caso ejercerá las funciones genéricas de Secretaría y asesoramiento jurídico en las materias propias del Departamento y las de control de legalidad y control del gasto de los Órganos del Departamento.","Corresponde al Diputado o Diputada Foral correspondiente, conjuntamente con el diputado o diputada foral que tenga atribuidas las competencias en materia de organización y servicios generales, la aprobación de la estructura orgánica de cada uno de los Departamentos mediante Orden Foral.","Los Departamentos estarán bajo la superior dirección de un director o directora general."],"a":1},{"id":104,"q":"Según la Norma Foral 6/2005, las disposiciones de carácter general de la Diputación Foral adoptarán la siguiente forma:","o":["Decretos Forales del Consejo de Gobierno Foral y del Diputado o Diputada General y Ordenes Forales, dictadas por las diputadas y diputados forales titulares de los Departamentos.","Acuerdos del Consejo de Gobierno Foral, Decretos Forales del Diputado o Diputada General y Ordenes Forales, dictadas por las diputadas y diputados forales titulares de los Departamentos.","Acuerdos del Consejo de Gobierno Foral y Ordenes Forales del Diputado o Diputada General y de las diputadas y diputados forales titulares de los Departamentos.","Decretos Forales del Consejo de Gobierno Foral y Ordenes Forales del Diputado o Diputada General y de las diputadas y diputados forales titulares de los Departamentos."],"a":0},{"id":105,"q":"Según la Norma Foral, 6/2005, todas las disposiciones de carácter general:","o":["Se publicarán en el Boletín Oficial de Gipuzkoa y entrarán en vigor a los 15 días de su publicación, salvo disposición en contrario.","Se publicarán en el Boletín Oficial de Gipuzkoa y en el Boletín Oficial del País Vasco y entrarán en vigor a los 15 días de su publicación, salvo disposición en contrario.","Se publicarán en el Boletín Oficial de Gipuzkoa y entrarán en vigor a los 20 días de su publicación, salvo disposición en contrario.","Se publicarán en el Boletín Oficial de Gipuzkoa y en el Boletín Oficial del País Vasco y entrarán en vigor a los 20 días de su publicación, salvo disposición en contrario."],"a":2},{"id":106,"q":"Según la Norma Foral, 6/2005, los actos del Consejo de Gobierno Foral adoptarán la forma de:","o":["Acuerdo.","Decreto Foral.","Orden Foral.","Resolución."],"a":0},{"id":107,"q":"Según la Norma Foral, 6/2005, las resoluciones del Diputado o Diputada General adoptarán la forma de:","o":["Acuerdo.","Decreto Foral.","Orden Foral.","Resolución."],"a":1},{"id":108,"q":"Según la Norma Foral, 6/2005, las resoluciones de las diputadas y diputados forales adoptarán la forma de:","o":["Acuerdo.","Decreto Foral.","Orden Foral.","Resolución."],"a":2},{"id":109,"q":"Según la Norma Foral, 6/2005, los actos dictados por las directoras y directores generales adoptarán la forma de:","o":["Acuerdo.","Decreto Foral.","Orden Foral.","Resolución."],"a":3},{"id":110,"q":"Según la Norma Foral, 6/2005, las resoluciones dictadas por las diputadas y diputados forales:","o":["No ponen fin a la vía administrativa.","Ponen fin a la vía administrativa.","No ponen fin a la vía administrativa, salvo que se señale lo contrario en la propia resolución.","Ponen fin a la vía administrativa, salvo que se señale lo contrario en la propia resolución."],"a":1},{"id":111,"q":"De acuerdo con la Ley 39/2015, los procedimientos:","o":["Se iniciarán siempre de oficio.","Se iniciarán siempre a solicitud del interesado.","Podrán iniciarse de oficio o a solicitud del interesado.","Podrán iniciarse de oficio o a solicitud de los interesados, cuando el número de interesados sea significativo."],"a":2},{"id":112,"q":"Iniciado el procedimiento, el órgano administrativo competente para resolver:","o":["Podrá adoptar, únicamente de oficio y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la resolución que pudiera recaer, si existiesen elementos de juicio suficientes para ello, de acuerdo con los principios de proporcionalidad, efectividad y menor onerosidad.","Podrá adoptar, de oficio o a instancia de parte y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la resolución que pudiera recaer, si existiesen elementos de juicio suficientes para ello, de acuerdo con los principios de proporcionalidad, efectividad y menor onerosidad.","Podrá adoptar, únicamente de oficio y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la resolución que pudiera recaer, con independencia de que existiesen elementos de juicio suficientes para ello.","Podrá adoptar, de oficio o a instancia de parte y de forma motivada, las medidas provisionales que estime oportunas para asegurar la eficacia de la resolución que pudiera recaer, con independencia de que existiesen elementos de juicio suficientes para ello."],"a":1},{"id":113,"q":"Antes de la iniciación del procedimiento administrativo, el órgano competente para iniciar o instruir el procedimiento, de oficio o a instancia de parte, podrá adoptar de forma motivada las medidas provisionales que resulten necesarias y proporcionadas:","o":["En los casos de urgencia inaplazable y para la protección provisional de los intereses implicados.","En todos los casos.","Solo en los procedimientos sancionadores.","Solo en los procedimientos de responsabilidad patrimonial."],"a":0},{"id":114,"q":"No se podrán adoptar medidas provisionales:","o":["Que puedan causar perjuicio de difícil o imposible reparación a los interesados o que impliquen violación de derechos amparados por las leyes.","Cuando así lo solicite la persona interesada.","Cuando el plazo para la resolución del procedimiento sea menor a 1 año.","Cuando otras administraciones públicas puedan ser afectadas por las medidas a adoptar y muestren su disconformidad en un plazo de 10 días"],"a":0},{"id":115,"q":"Señale la respuesta correcta. Los procedimientos se iniciarán de oficio por acuerdo del órgano competente:","o":["Exclusivamente por propia iniciativa o como consecuencia de orden superior.","Exclusivamente por propia iniciativa o a petición de otros órganos.","Bien por propia iniciativa o como consecuencia de orden superior, a petición de otros órganos o por denuncia.","Bien por propia iniciativa o como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia."],"a":3},{"id":116,"q":"Según la Ley 39/2015, se entiende por propia iniciativa:","o":["La actuación derivada del conocimiento directo o indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de iniciación.","La actuación derivada del conocimiento directo de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de iniciación.","La actuación derivada del conocimiento indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de iniciación.","La orden emitida por el órgano administrativo inmediatamente superior jerárquico del competente para la iniciación del procedimiento."],"a":0},{"id":117,"q":"Señale la respuesta correcta:","o":["Se entiende por denuncia, el acto por el que cualquier persona que acredite estar interesado en el procedimiento, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo la existencia de un determinado hecho que pudiera justificar la iniciación de oficio de un procedimiento administrativo.","Las denuncias deberán expresar la identidad de la persona o personas que las presentan y el relato de los hechos que se ponen en conocimiento de la Administración. Cuando dichos hechos pudieran constituir una infracción administrativa, recogerán la fecha de su comisión y deberán identificarse a los presuntos responsables.","Cuando la denuncia invocara un perjuicio en el patrimonio de las Administraciones Públicas la no iniciación del procedimiento deberá ser motivada y se notificará a los denunciantes la decisión de si se ha iniciado o no el procedimiento.","La presentación de una denuncia confiere, por sí sola, la condición de interesado en el procedimiento."],"a":2},{"id":118,"q":"Los procedimientos de naturaleza sancionadora:","o":["Se iniciarán siempre de oficio por acuerdo del órgano competente y establecerán la debida separación entre la fase instructora y la sancionadora, que no podrá encomendarse a órganos distintos.","Se iniciarán siempre de oficio por acuerdo del órgano competente y establecerán la debida separación entre la fase instructora y la sancionadora, que se encomendará a órganos distintos.","Podrán iniciarse de oficio o a solicitud del interesado y establecerán la debida separación entre la fase instructora y la sancionadora, que no podrá encomendarse a órganos distintos.","Podrán iniciarse de oficio o a solicitud del interesado y establecerán la debida separación entre la fase instructora y la sancionadora, que se encomendará a órganos distintos."],"a":1},{"id":119,"q":"Señale la respuesta INCORRECTA. Las solicitudes de iniciación de procedimiento que se formulen deberán contener:","o":["Nombre y apellidos del interesado y, en su caso, de la persona que lo represente.","Identificación del medio electrónico, o en su defecto, lugar físico en que desea que se practique la notificación. Adicionalmente, los interesados deberán aportar su dirección de correo electrónico y/o dispositivo electrónico con el fin de que las Administraciones Públicas les avisen del envío o puesta a disposición de la notificación.","Hechos, razones y petición en que se concrete, con toda claridad, la solicitud.","Órgano, centro o unidad administrativa a la que se dirige y su correspondiente código de identificación."],"a":1},{"id":120,"q":"Con carácter general, en los procedimientos de responsabilidad patrimonial:","o":["El derecho a reclamar prescribirá a los seis meses de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo.","El derecho a reclamar prescribirá al año de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo.","El derecho a reclamar prescribirá a los dos años de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo.","El derecho a reclamar no prescribe."],"a":1},{"id":121,"q":"Según la Ley 39/2015, si la solicitud de iniciación de un procedimiento administrativos no reúne los requisitos exigidos:","o":["Se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21.","Se requerirá al interesado para que, en un plazo improrrogable de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21.","Se requerirá al interesado para que, en un plazo improrrogable de quince días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21.","La solicitud será inadmitida."],"a":0},{"id":122,"q":"Según el artículo 68 de la Ley 39/2015, el plazo de subsanación o mejora de una solicitud podrá ser ampliado prudencialmente:","o":["En los procedimientos selectivos.","En los procedimientos de concurrencia competitiva.","En cualquier tipo de procedimiento.","En cualquier tipo de procedimiento, siempre que no se trate de procedimientos selectivos o de concurrencia competitiva."],"a":3},{"id":123,"q":"A los efectos de la Ley 39/2015, se entenderá por declaración responsable:","o":["El documento suscrito por un interesado en el que éste manifiesta, bajo su responsabilidad, que cumple con los requisitos establecidos en la normativa vigente para obtener el reconocimiento de un derecho o facultad o para su ejercicio, que dispone de la documentación que así lo acredita, que la pondrá a disposición de la Administración cuando le sea requerida, y que se compromete a mantener el cumplimiento de las anteriores obligaciones durante el período de tiempo inherente a dicho reconocimiento o ejercicio.","Aquel documento mediante el que los interesados ponen en conocimiento de la Administración Pública competente sus datos identificativos o cualquier otro dato relevante para el inicio de una actividad o el ejercicio de un derecho.","El certificado técnico firmado por un profesional colegiado que garantiza que una obra o instalación cumple con todas las medidas de seguridad exigidas por la ley.","El documento emitido por la Administración Pública que autoriza al interesado a iniciar una actividad económica tras haber pagado las tasas correspondientes."],"a":0},{"id":124,"q":"A los efectos de la Ley 39/2015, se entenderá por comunicación:","o":["El documento suscrito por un interesado en el que éste manifiesta, bajo su responsabilidad, que cumple con los requisitos establecidos en la normativa vigente para obtener el reconocimiento de un derecho o facultad o para su ejercicio, que dispone de la documentación que así lo acredita, que la pondrá a disposición de la Administración cuando le sea requerida, y que se compromete a mantener el cumplimiento de las anteriores obligaciones durante el período de tiempo inherente a dicho reconocimiento o ejercicio.","Aquel documento mediante el que los interesados ponen en conocimiento de la Administración Pública competente sus datos identificativos o cualquier otro dato relevante para el inicio de una actividad o el ejercicio de un derecho.","El certificado técnico firmado por un profesional colegiado que garantiza que una obra o instalación cumple con todas las medidas de seguridad exigidas por la ley.","El documento emitido por la Administración Pública que autoriza al interesado a iniciar una actividad económica tras haber pagado las tasas correspondientes."],"a":1},{"id":125,"q":"Según la Ley 39/2015, se entiende por expediente administrativo:","o":["El conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa, así como las diligencias encaminadas a ejecutarla.","Es el documento único y definitivo, firmado por la autoridad competente, que pone fin a un procedimiento y agota la vía administrativa.","Es la suma de los recursos económicos y materiales que una unidad administrativa asigna para la tramitación de un procedimiento de licitación pública.","Es el sistema informático y la base de datos donde se almacenan exclusivamente las notas, borradores y comunicaciones internas que los funcionarios intercambian durante un proceso."],"a":0},{"id":126,"q":"Según la Ley 39/2015, los trámites que deban ser cumplimentados por los interesados:","o":["Deberán realizarse en el plazo de quince días a partir del siguiente al envío de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.","Deberán realizarse en el plazo de diez días a partir del siguiente al envío de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.","Deberán realizarse en el plazo de quince días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.","Deberán realizarse en el plazo de diez días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto."],"a":3},{"id":127,"q":"Según la Ley 39/2015, señale la respuesta correcta:","o":["Los interesados podrán, en cualquier momento del procedimiento anterior a la resolución de la misma, aducir alegaciones y aportar documentos u otros elementos de juicio.","Los interesados solo podrán aducir alegaciones y aportar documentos u otros elementos de juicio cuando así lo solicite el órgano instructor.","Los interesados podrán, en cualquier momento del procedimiento anterior al trámite de audiencia, aducir alegaciones y aportar documentos u otros elementos de juicio.","Los interesados no podrán aducir alegaciones y aportar documentos u otros elementos de juicio una vez iniciado el procedimiento."],"a":2},{"id":128,"q":"Salvo disposición expresa en contrario, los informes serán:","o":["Facultativos y vinculantes.","Facultativos y no vinculantes.","Preceptivos y vinculantes.","Preceptivos y no vinculantes."],"a":1},{"id":129,"q":"El informe emitido fuera de plazo:","o":["Podrá no ser tenido en cuenta al adoptar la correspondiente resolución.","No podrá ser tenido en cuenta al adoptar la correspondiente resolución.","Deberá ser tenido en cuenta al adoptar la correspondiente resolución, siempre y cuando se haya emitido antes de la resolución.","Deberá ser tenido en cuenta al adoptar la correspondiente resolución, siempre y cuando se haya emitido antes del trámite de audiencia."],"a":0},{"id":130,"q":"Según la Ley 39/2015, en los procedimientos de responsabilidad patrimonial será preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma:","o":["Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica, así como en aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del Consejo de Estado.","Únicamente cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica.","Únicamente en aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del Consejo de Estado.","En todos los casos."],"a":0},{"id":131,"q":"Según la Ley 39/2015, respecto al trámite de audiencia:","o":["Los interesados, en un plazo inferior a diez días, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes.","Los interesados, en un plazo inferior a quince días, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes.","Los interesados, en un plazo no inferior a quince días ni superior a veinte, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes.","Los interesados, en un plazo no inferior a diez días ni superior a quince, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes."],"a":3},{"id":132,"q":"Señale la respuesta correcta respecto a la información pública regulada en la Ley 39/2015:","o":["El órgano instructor del procedimiento, cuando la naturaleza de éste lo requiera, podrá acordar un período de información pública.","Se publicará un anuncio en la sede electrónica correspondiente a fin de que cualquier persona física o jurídica pueda examinar el expediente, o la parte del mismo que se acuerde.","La incomparecencia en este trámite no impedirá a los interesados interponer los recursos procedentes contra la resolución definitiva del procedimiento.","La comparecencia en el trámite de información pública otorga, por sí misma, la condición de interesado."],"a":2},{"id":133,"q":"Señale la respuesta INCORRECTA respecto a la resolución:","o":["Antes de dictar resolución, el órgano competente para resolver podrá decidir, mediante acuerdo motivado, la realización de las actuaciones complementarias indispensables para resolver el procedimiento.","La resolución que ponga fin al procedimiento decidirá todas las cuestiones planteadas por los interesados y aquellas otras derivadas del mismo.","Cuando se trate de cuestiones conexas que no hubieran sido planteadas por los interesados, el órgano competente no podrá pronunciarse sobre las mismas.","En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas por éste, sin que en ningún caso pueda agravar su situación inicial y sin perjuicio de la potestad de la Administración de incoar de oficio un nuevo procedimiento, si procede."],"a":2},{"id":134,"q":"El interesado:","o":["Podrá desistir de su solicitud o, cuando ello no esté prohibido por el ordenamiento jurídico, renunciar a sus derechos.","Podrá desistir de su solicitud o, cuando ello no esté prohibido por el ordenamiento jurídico, renunciar a sus derechos en un plazo de diez desde su presentación. Finalizado el plazo, la Administración podrá no aceptar el desistimiento o la renuncia.","Podrá desistir de su solicitud o, cuando ello no esté prohibido por el ordenamiento jurídico, renunciar a sus derechos, previo pago de una compensación económica.","No podrá desistir de su solicitud o renunciar a sus derechos."],"a":0},{"id":135,"q":"Con arreglo a lo dispuesto en la Ley 39/2015, salvo que reste menos para su tramitación ordinaria, ¿en qué tiempo deberán ser resueltos los procedimientos administrativos tramitados de manera simplificada?","o":["Diez días, a contar desde la notificación al interesado del acuerdo de tramitación simplificada del procedimiento.","Treinta días, a contar desde la notificación al interesado del acuerdo de tramitación simplificada del procedimiento.","Diez días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.","Treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento."],"a":3},{"id":136,"q":"El objeto de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, es regular los requisitos de validez y eficacia de los actos administrativos, el procedimiento administrativo común a todas las Administraciones Públicas, incluyendo el sancionador y el de:","o":["Responsabilidad penal de las autoridades.","Reclamación de deudas entre particulares.","Responsabilidad de las Administraciones Públicas.","Selección de personal estatutario."],"a":2},{"id":137,"q":"La Ley 39/2015 se aplica al sector público, el cual comprende, según el artículo 2.1.c):","o":["Las empresas privadas con participación estatal mínima del 10 %.","Las organizaciones sindicales y empresariales.","Las entidades que integran la Administración Local.","Los partidos políticos y las fundaciones vinculadas a ellos."],"a":2},{"id":138,"q":"A los efectos previstos en la Ley 39/2015, tienen capacidad de obrar ante las Administraciones Públicas:","o":["Solo los mayores de edad.","Los menores de edad para el ejercicio y defensa de aquellos de sus derechos e intereses cuya actuación esté permitida por el ordenamiento jurídico sin la asistencia de la persona que ejerza la patria potestad, tutela o curatela. Se exceptúa el supuesto de los menores incapacitados, cuando la extensión de la incapacitación afecte al ejercicio y defensa de los derechos o intereses de que se trate.","Los menores de edad para el ejercicio y defensa de aquellos de sus derechos e intereses cuya actuación esté permitida por el ordenamiento jurídico sin la asistencia de la persona que ejerza la patria potestad, tutela o curatela, incluyendo los menores incapacitados, incluso cuando la extensión de la incapacitación afecte al ejercicio y defensa de los derechos o intereses de que se trate.","En todo caso, los grupos de afectados, las uniones y entidades sin personalidad jurídica y los patrimonios independientes o autónomos."],"a":1},{"id":139,"q":"Según la Ley 39/2015, se consideran interesados en el procedimiento administrativo:","o":["Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos.","Los que, sin haber iniciado el procedimiento, tengan intereses personales que puedan resultar afectados por la decisión que en el mismo se adopte.","Aquellos cuyos intereses legítimos, individuales o colectivos, puedan resultar afectados por la resolución y se personen en el procedimiento una vez haya recaído resolución definitiva.","Todas las personas con capacidad de obrar."],"a":0},{"id":140,"q":"Según la Ley 39/2015, señale la respuesta correcta:","o":["Para formular solicitudes en nombre de otra persona, deberá acreditarse la representación. Para presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos y para los actos y gestiones de mero trámite, se presumirá aquella representación.","Para formular solicitudes, presentar declaraciones responsables o comunicaciones en nombre de otra persona, deberá acreditarse la representación. Para interponer recursos, desistir de acciones y renunciar a derechos y para los actos y gestiones de mero trámite, se presumirá aquella representación.","Para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos en nombre de otra persona, deberá acreditarse la representación. Para desistir de acciones y renunciar a derechos y para los actos y gestiones de mero trámite, se presumirá aquella representación.","Para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos en nombre de otra persona, deberá acreditarse la representación. Para los actos y gestiones de mero trámite se presumirá aquella representación."],"a":3},{"id":141,"q":"Según la Ley 39/2015, cuando en una solicitud, escrito o comunicación figuren varios interesados, las actuaciones a que den lugar se efectuarán:","o":["Con todos ellos.","Con el representante o el interesado que expresamente hayan señalado, y, en su defecto, con el que figure en primer término.","Con el representante o el interesado que expresamente hayan señalado, y, en su defecto, con el que tenga mayor edad.","Con el que tenga mayor edad."],"a":1},{"id":142,"q":"Según la Ley 39/2015, para interponer recursos las Administraciones Públicas requerirán a los interesados:","o":["El uso obligatorio de firma.","Que actúen mediante un abogado de forma obligatoria.","Que actúen mediante un abogado de forma obligatoria, si se trata de un recurso de alzada.","Que únicamente acrediten previamente su identidad a través de cualquiera de los medios de identificación previstos en la Ley."],"a":0},{"id":143,"q":"Según la Ley 39/2015, señale la respuesta correcta:","o":["Los empleados de las Administraciones Públicas para los trámites y actuaciones que realicen con ellas por razón de su condición de empleado público, podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no.","Las entidades sin personalidad jurídica podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas.","Las personas jurídicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas.","Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas."],"a":3},{"id":144,"q":"Según la Ley 39/2015, en todo caso, estarán obligados a relacionarse a través de medios electrónicos con las Administraciones Públicas:","o":["Las personas físicas.","Las personas jurídicas.","Las personas físicas y las personas jurídicas.","Las personas físicas, las personas jurídicas y las entidades sin personalidad jurídica."],"a":1},{"id":145,"q":"Según la Ley 39/2015, la Administración:","o":["Está obligada a dictar resolución expresa y a notificarla en todos los procedimientos cualquiera que sea su forma de iniciación, exceptuando los supuestos de terminación del procedimiento por pacto o convenio, así como los procedimientos relativos al ejercicio de derechos sometidos únicamente al deber de declaración responsable o comunicación a la Administración.","Está obligada, en todo caso, a dictar resolución expresa y a notificarla en todos los procedimientos cualquiera que sea su forma de iniciación.","No está obligada a dictar resolución expresa y a notificarla en los casos de prescripción, renuncia del derecho, caducidad del procedimiento o desistimiento de la solicitud, así como de desaparición sobrevenida del objeto del procedimiento.","No está obligada a dictar resolución expresa y a notificarla en ningún caso."],"a":0},{"id":146,"q":"Según la Ley 39/2015, el transcurso del plazo máximo legal para resolver un procedimiento y notificar la resolución se suspenderá en el siguiente caso:","o":["Cuando deba requerirse a cualquier interesado para la subsanación de deficiencias o la aportación de documentos y otros elementos de juicio necesarios, por el tiempo que medie entre la notificación del requerimiento y su efectivo cumplimiento por el destinatario, o, en su defecto, por el del plazo concedido, todo ello sin perjuicio de lo previsto en el artículo 68 de la Ley 39/2015.","Cuando deba obtenerse un pronunciamiento previo y preceptivo de un órgano de la Unión Europea, por el tiempo que medie entre la petición, que habrá de comunicarse a los interesados, y la notificación del pronunciamiento a la Administración instructora, que también deberá serles comunicada.","Cuando los interesados promuevan la recusación en cualquier momento de la tramitación de un procedimiento, desde que ésta se plantee hasta que sea resuelta por el superior jerárquico del recusado.","Cuando se soliciten informes preceptivos a un órgano de la misma o distinta Administración, por el tiempo que medie entre la petición, que deberá comunicarse a los interesados, y la recepción del informe, que igualmente deberá ser comunicada a los mismos. Este plazo de suspensión no podrá exceder en ningún caso de tres meses. En caso de no recibirse el informe en el plazo indicado, proseguirá el procedimiento."],"a":2},{"id":147,"q":"Según la Ley 39/2015, señale la respuesta correcta respecto a los procedimientos iniciados a solicitud del interesado:","o":["La resolución expresa posterior a la producción del acto sólo podrá dictarse de ser confirmatoria del mismo.","La resolución expresa posterior a la producción del acto se adoptará por la Administración sin vinculación alguna al sentido del silencio.","En los casos de estimación por silencio administrativo, la resolución expresa posterior a la producción del acto sólo podrá dictarse de ser confirmatoria del mismo y en los casos de desestimación por silencio administrativo, la resolución expresa posterior al vencimiento del plazo se adoptará por la Administración sin vinculación alguna al sentido del silencio.","En los casos de estimación por silencio administrativo, la resolución expresa posterior a la producción del acto se adoptará por la Administración sin vinculación alguna al sentido del silencio y en los casos de desestimación por silencio administrativo, la resolución expresa posterior al vencimiento del plazo sólo podrá dictarse de ser confirmatoria del mismo."],"a":2},{"id":148,"q":"Según la Ley 39/2015, en los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos, el vencimiento del plazo máximo sin resolución expresa:","o":["Producirá la caducidad del procedimiento.","Permitirá a los interesados entender estimadas sus pretensiones por silencio administrativo, salvo en los procedimientos relativos al ejercicio del derecho de petición.","Permitirá a los interesados entender estimadas sus pretensiones por silencio administrativo.","Permitirá a los interesados entender desestimadas sus pretensiones por silencio administrativo."],"a":3},{"id":149,"q":"Según la Ley 39/2015, tendrán la consideración de copias auténticas de un documento público administrativo:","o":["Las fotocopias simples realizadas por el interesado.","Las realizadas por los órganos competentes de las Administraciones Públicas en las que quede garantizada la identidad del órgano que ha realizado la copia y su contenido.","Cualquier documento escaneado enviado por correo electrónico.","Las fotografías realizadas con un dispositivo móvil, siempre y cuando se envíen posteriormente mediante firma electrónica autorizada del interesado."],"a":1},{"id":150,"q":"Según la Ley 39/2015, los interesados tienen derecho a no aportar documentos que:","o":["Consideren confidenciales o íntimos.","Ya se encuentren en poder de la Administración actuante o hayan sido elaborados por cualquier otra Administración.","Tengan una antigüedad superior a 5 años.","Tengan un coste de expedición superior a 20 euros."],"a":1},{"id":151,"q":"Según la Ley 39/2015, siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días:","o":["Se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.","Se entiende que éstos son naturales, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.","Se entiende que éstos son hábiles, excluyéndose del cómputo los domingos y los declarados festivos.","Se entiende que éstos son naturales, excluyéndose del cómputo los domingos y los declarados festivos."],"a":0},{"id":152,"q":"Según la Ley 39/2015, señale la respuesta correcta respecto al cómputo de plazos:","o":["Los plazos expresados por horas se contarán de hora en hora y de minuto en minuto desde la hora y minuto en que tenga lugar la notificación o publicación del acto de que se trate y no podrán tener una duración superior a cuarenta y ocho horas, en cuyo caso se expresarán en días.","Los plazos expresados en días se contarán a partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto de que se trate, o desde el siguiente a aquel en que se produzca la estimación o la desestimación por silencio administrativo.","Cuando el último día del plazo sea inhábil, se entenderá que el plazo expira en el primer día hábil anterior.","Si el plazo se fija en meses, si en el mes de vencimiento no hubiera día equivalente a aquel en que comienza el cómputo, se entenderá que el plazo expira el primer día del siguiente mes."],"a":1},{"id":153,"q":"Según la Ley 39/2015, señale la respuesta correcta respecto a las reglas de funcionamiento del registro electrónico:","o":["Permitirá la presentación de documentos todos los días hábiles del año durante las veinticuatro horas.","Permitirá la presentación de documentos todos los días hábiles del año durante la jornada laboral de la Administración Pública correspondiente.","A los efectos del cómputo de plazo fijado en días hábiles, y en lo que se refiere al cumplimiento de plazos por los interesados, la presentación en un día inhábil se entenderá realizada en la primera hora del primer día hábil siguiente salvo que una norma permita expresamente la recepción en día inhábil.","A los efectos del cómputo de plazo fijado en días hábiles, y en lo que se refiere al cumplimiento de plazos por los interesados, la presentación en un día inhábil se entenderá el primer día hábil anterior."],"a":2},{"id":154,"q":"Según la Ley 39/2015, señale la respuesta correcta respecto a la ampliación de plazos:","o":["La Administración, salvo precepto en contrario, podrá conceder de oficio o a petición de los interesados, una ampliación de los plazos establecidos, que no exceda de la mitad de los mismos, si las circunstancias lo aconsejan, aun cuando con ello se perjudiquen derechos de terceros.","La petición de los interesados sobre la ampliación deberá producirse, en todo caso, antes del vencimiento del plazo de que se trate y la decisión sobre la ampliación deberá adoptarse dentro de los diez días hábiles siguiente al vencimiento del plazo.","Cuando una incidencia técnica haya imposibilitado el funcionamiento ordinario del sistema o aplicación que corresponda, y hasta que se solucione el problema, la Administración podrá determinar una ampliación de los plazos no vencidos, debiendo publicar en la sede electrónica tanto la incidencia técnica acontecida como la ampliación concreta del plazo no vencido.","Los acuerdos sobre ampliación de plazos o sobre su denegación podrán recurrirse de acuerdo con lo previsto en el artículo 112 y siguientes de la ley."],"a":2},{"id":155,"q":"Según la Ley 39/2015, los actos administrativos se producirán por escrito a través de medios electrónicos, a menos que:","o":["El interesado sea una persona física.","El interesado solicite que se realice a través de otros medios.","Una incidencia técnica lo impida, en cuyo caso se realizará de forma verbal.","Su naturaleza exija otra forma más adecuada de expresión y constancia."],"a":3},{"id":156,"q":"Según la Ley 39/2015, señale la respuesta correcta respecto a la notificación:","o":["Toda notificación deberá ser cursada dentro del plazo de quince días a partir de la fecha en que el acto haya sido dictado.","La notificación deberá contener el texto íntegro de la resolución, con indicación de si pone fin o no a la vía administrativa, la expresión de los recursos que procedan, en su caso, en vía administrativa y judicial, el órgano ante el que hubieran de presentarse y el plazo para interponerlos, sin perjuicio de que los interesados puedan ejercitar, en su caso, cualquier otro que estimen procedente.","Las notificaciones que, conteniendo el texto íntegro del acto, omitiesen alguno de los demás requisitos previstos en el apartado anterior, surtirán efecto a desde la fecha en que se dicten, siempre y cuando el interesado realice actuaciones que supongan el conocimiento del contenido y alcance de la resolución o acto objeto de la notificación, o interponga cualquier recurso que proceda.","Con independencia de que la notificación se realice en papel o por medios electrónicos, las Administraciones Públicas enviarán un aviso al dispositivo electrónico y/o a la dirección de correo electrónico del interesado que éste haya comunicado, informándole de la puesta a disposición de una notificación en la sede electrónica de la Administración u Organismo correspondiente o en la dirección electrónica habilitada única. La falta de práctica de este aviso impedirá que la notificación sea considerada plenamente válida."],"a":1},{"id":157,"q":"Según la Ley 39/2015, en las notificaciones practicadas en papel, de no hallarse presente el interesado en el momento de la entrega, podrá hacerse cargo de la misma:","o":["Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad.","Cualquier persona mayor de 14 años que sea familiar de primer grado y que se encuentre en el domicilio y haga constar su identidad.","Cualquier vecino mayor de edad y haga constar su identidad.","Cualquier persona mayor de edad que se encuentre en el domicilio y haga constar su identidad."],"a":0},{"id":158,"q":"Según la Ley 39/2015, en todo caso, los actos administrativos serán objeto de publicación, surtiendo ésta los efectos de la notificación, entre otros, en el siguiente caso:","o":["Cuando se trate de actos que limiten derechos subjetivos o intereses legítimos.","Cuando se trate de actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos.","Cuando se trate de actos que acuerden la terminación del procedimiento por la imposibilidad material de continuarlo por causas sobrevenidas, así como cuando acuerden el desistimiento por la Administración en procedimientos iniciados de oficio.","Cuando se trate de actos integrantes de un procedimiento selectivo o de concurrencia competitiva de cualquier tipo. En este caso, la convocatoria del procedimiento deberá indicar el medio donde se efectuarán las sucesivas publicaciones, careciendo de validez las que se lleven a cabo en lugares distintos."],"a":3},{"id":159,"q":"Según la Ley 39/2015, son anulables los actos de la Administración que:","o":["Lesionen los derechos y libertades susceptibles de amparo constitucional.","Sean constitutivos de infracción penal o se dicten como consecuencia de ésta.","Se dicten prescindiendo total y absolutamente del procedimiento legalmente establecido o de las normas que contienen las reglas esenciales para la formación de la voluntad de los órganos colegiados.","Incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder."],"a":3},{"id":160,"q":"Señale la respuesta correcta respecto a los límites a la extensión de la nulidad o anulabilidad de los actos:","o":["La nulidad o anulabilidad de un acto implicará la de los sucesivos en el procedimiento.","La nulidad o anulabilidad en parte del acto administrativo implicará la de las partes del mismo independientes de aquélla.","El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción.","La Administración podrá convalidar los actos nulos."],"a":2},{"id":161,"q":"Según la Ley 39/2015, las Administraciones Públicas, en cualquier momento, por iniciativa propia o a solicitud de interesado, declararán de oficio la nulidad de los actos administrativos que hayan puesto fin a la vía administrativa o que no hayan sido recurridos en plazo, siempre que:","o":["Sean actos desfavorables para el interesado.","Concurra alguna de las causas de nulidad de pleno derecho previstas en el artículo 47.1 de la Ley 39/2015.","El error sea de carácter puramente material o aritmético.","Haya pasado menos de un año desde su notificación."],"a":1},{"id":162,"q":"Podrán interponerse por los interesados los recursos de alzada y potestativo de reposición, que cabrá fundar en cualquiera de los motivos de nulidad o anulabilidad previstos en los artículos 47 y 48 de la Ley 39/2015:","o":["Contra las resoluciones y los actos de trámite.","Contra las resoluciones y los actos de trámite que pongan fin a la vía administrativa.","Contra las resoluciones y los actos de trámite que no pongan fin a la vía administrativa.","Contra las resoluciones y los actos de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos e intereses legítimos."],"a":3},{"id":163,"q":"Según la Ley 39/2015, haber transcurrido el plazo para la interposición del recurso:","o":["Será causa de desestimación del recurso.","Será causa de desestimación del recurso, salvo que se trate de un recurso potestativo de revisión.","Será causa de inadmisión del recurso.","Será causa de inadmisión del recurso, salvo que se trate de un recurso potestativo de revisión."],"a":2},{"id":164,"q":"Señale la respuesta correcta respecto a los recursos de alzada:","o":["El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos. El plazo máximo para dictar y notificar la resolución será de tres meses.","El plazo para la interposición del recurso de alzada será de tres meses, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos. El plazo máximo para dictar y notificar la resolución será de un mes.","El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso. Transcurrido dicho plazo, únicamente podrá interponerse recurso contencioso-administrativo, sin perjuicio, en su caso, de la procedencia del recurso extraordinario de revisión.","El plazo para la interposición del recurso de alzada será de tres meses, si el acto fuera expreso. Transcurrido dicho plazo, únicamente podrá interponerse recurso contencioso-administrativo, sin perjuicio, en su caso, de la procedencia del recurso extraordinario de revisión."],"a":0},{"id":165,"q":"Señale la respuesta correcta respecto a los recursos potestativos de reposición:","o":["El plazo para la interposición del recurso de reposición será de un mes, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos. El plazo máximo para dictar y notificar la resolución será de tres meses.","El plazo para la interposición del recurso de reposición será de tres meses, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos. El plazo máximo para dictar y notificar la resolución será de un mes.","El plazo para la interposición del recurso de reposición será de un mes, si el acto fuera expreso. Transcurrido dicho plazo, únicamente podrá interponerse recurso contencioso-administrativo, sin perjuicio, en su caso, de la procedencia del recurso extraordinario de revisión.","El plazo para la interposición del recurso de reposición será de tres meses, si el acto fuera expreso. Transcurrido dicho plazo, únicamente podrá interponerse recurso contencioso-administrativo, sin perjuicio, en su caso, de la procedencia del recurso extraordinario de revisión."],"a":2},{"id":166,"q":"Según la Ley 40/2015, para la válida constitución del órgano, a efectos de la celebración de sesiones, deliberaciones y toma de acuerdos:","o":["Se requerirá la asistencia presencial, del Presidente y Secretario o en su caso, de quienes les suplan, y la asistencia, presencial o a distancia, de la mitad, al menos, de sus miembros.","Se requerirá la asistencia presencial, del Presidente y Secretario o en su caso, de quienes les suplan, y la asistencia, presencial o a distancia, de dos tercios, al menos, de sus miembros.","Se requerirá la asistencia, presencial o a distancia, del Presidente y Secretario o en su caso, de quienes les suplan, y la de la mitad, al menos, de sus miembros.","Se requerirá la asistencia, presencial o a distancia, del Presidente y Secretario o en su caso, de quienes les suplan, y de dos tercios, al menos, de sus miembros."],"a":2},{"id":167,"q":"Según la Ley 40/2015, es un motivo de abstención:","o":["Tener un vínculo matrimonial o situación de hecho asimilable y el parentesco de consanguinidad o afinidad dentro del cuarto grado, con cualquiera de los interesados, con los administradores de entidades o sociedades interesadas y también con los asesores, representantes legales o mandatarios que intervengan en el procedimiento, así como compartir despacho profesional o estar asociado con éstos para el asesoramiento, la representación o el mandato.","Tener amistad íntima o enemistad con cualquiera de los interesados, con los administradores de entidades o sociedades interesadas y también con los asesores, representantes legales o mandatarios que intervengan en el procedimiento, así como compartir despacho profesional o estar asociado con éstos para el asesoramiento, la representación o el mandato.","Haber intervenido como perito o como testigo en cualquier procedimiento de la Administración Pública.","Tener relación de servicio con persona natural o jurídica interesada directamente en el asunto, o haberle prestado en los cuatro últimos años servicios profesionales de cualquier tipo y en cualquier circunstancia o lugar."],"a":1},{"id":168,"q":"Según la Ley 40/2015, podrá promoverse recusación por los interesados:","o":["Solo antes de que se inicie el procedimiento.","En cualquier momento de la tramitación del procedimiento.","Únicamente tras dictarse la resolución final.","En cualquier momento de la tramitación del procedimiento, únicamente cuando el motivo de recusación sea tener interés personal en el asunto de que se trate o en otro en cuya resolución pudiera influir la de aquél."],"a":1},{"id":169,"q":"Según la Ley 40/2015, la sede electrónica es:","o":["Aquella dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública, o bien a una o varios organismos públicos o entidades de Derecho Público en el ejercicio de sus competencias.","Aquella dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública, o bien a una o varios organismos públicos o entidades de Derecho Público o a una entidad privada en el ejercicio de sus competencias.","El punto de acceso electrónico cuya titularidad corresponda a una Administración Pública, organismo público o entidad de Derecho Público que permite el acceso a través de internet a la información publicada.","El punto de acceso electrónico cuya titularidad corresponda a una Administración Pública, organismo público, entidad de Derecho Público o entidad privada, que permite el acceso a través de internet a la información publicada."],"a":0},{"id":170,"q":"Según la Ley 40/2015, se entiende por portal de internet:","o":["Aquella dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública, o bien a una o varios organismos públicos o entidades de Derecho Público en el ejercicio de sus competencias.","Aquella dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública, o bien a una o varios organismos públicos o entidades de Derecho Público o a una entidad privada en el ejercicio de sus competencias.","El punto de acceso electrónico cuya titularidad corresponda a una Administración Pública, organismo público o entidad de Derecho Público que permite el acceso a través de internet a la información publicada.","El punto de acceso electrónico cuya titularidad corresponda a una Administración Pública, organismo público, entidad de Derecho Público o entidad privada, que permite el acceso a través de internet a la información publicada."],"a":3},{"id":171,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, los empleados públicos se clasifican en:","o":["Funcionarios de carrera y funcionarios interinos.","Funcionarios de carrera, funcionarios interinos, personal laboral, ya sea fijo, por tiempo indefinido o temporal y personal directivo profesional.","Funcionarios de carrera, funcionarios interinos, personal eventual y personal directivo profesional.","Funcionarios de carrera, funcionarios interinos, personal laboral, ya sea fijo, por tiempo indefinido o temporal y personal eventual."],"a":3},{"id":172,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, son funcionarios de carrera:","o":["Quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.","Los que, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter temporal para el desempeño de funciones propias de funcionarios de carrera, cuando se den determinadas circunstancias.","Los que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, prestan servicios retribuidos por las Administraciones Públicas.","Los que, en virtud de nombramiento y con carácter no permanente, sólo realizan funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin."],"a":0},{"id":173,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, son funcionarios interinos:","o":["Quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.","Los que, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter temporal para el desempeño de funciones propias de funcionarios de carrera, cuando se den determinadas circunstancias.","Los que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, prestan servicios retribuidos por las Administraciones Públicas.","Los que, en virtud de nombramiento y con carácter no permanente, sólo realizan funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin."],"a":1},{"id":174,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, podrán ser nombrados funcionarios interinos en la siguiente circunstancia:","o":["La existencia de plazas vacantes, cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de cuatro años.","La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario.","La ejecución de programas de carácter temporal, que no podrán tener una duración superior a cuatro años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo de este Estatuto.","El exceso o acumulación de tareas por plazo máximo de doce meses, dentro de un periodo de dieciocho meses."],"a":1},{"id":175,"q":"Los procedimientos de selección del personal funcionario interino serán públicos, rigiéndose en todo caso por los principios de:","o":["Igualdad, mérito, capacidad, confidencialidad y celeridad.","Discrecionalidad, publicidad y celeridad.","Idoneidad, publicidad y celeridad.","Igualdad, mérito, capacidad, publicidad y celeridad."],"a":3},{"id":176,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, es personal laboral:","o":["Quien, en virtud de nombramiento legal, está vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.","El que, por razones expresamente justificadas de necesidad y urgencia, es nombrado como tal con carácter temporal para el desempeño de funciones propias de funcionarios de carrera, cuando se den determinadas circunstancias.","El que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas.","El que, en virtud de nombramiento y con carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin."],"a":2},{"id":177,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, en función de la duración del contrato, el personal laboral podrá ser:","o":["Permanente o transitorio.","Funcionario o laboral.","Fijo, por tiempo indefinido o temporal.","Únicamente interino o eventual."],"a":2},{"id":178,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, es personal eventual:","o":["Quien, en virtud de nombramiento legal, está vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.","El que, por razones expresamente justificadas de necesidad y urgencia, es nombrado como tal con carácter temporal para el desempeño de funciones propias de funcionarios de carrera, cuando se den determinadas circunstancias.","El que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas.","El que, en virtud de nombramiento y con carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin."],"a":3},{"id":179,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, el cese del personal eventual se producirá, en todo caso:","o":["Cuando se produzca el de la autoridad a la que se preste la función de confianza o asesoramiento.","Cuando se convoquen elecciones.","Cuando se cumplan tres años desde su nombramiento.","Cuando se cumplan cuatro años desde su nombramiento."],"a":0},{"id":180,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, la carrera vertical consiste en:","o":["La progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo.","El ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos en el capítulo III del título V del Estatuto Básico del Empleado Público.","El ascenso desde un cuerpo o escala de un Subgrupo, o Grupo de clasificación profesional en el supuesto de que éste no tenga Subgrupo, a otro superior, de acuerdo con lo establecido en el artículo 18 del Estatuto Básico del Empleado Público.","El acceso a cuerpos o escalas del mismo Subgrupo profesional, de acuerdo con lo dispuesto en el artículo 18 del Estatuto Básico del Empleado Público."],"a":1},{"id":181,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, las retribuciones básicas son:","o":["Las que retribuyen al funcionario según la adscripción de su cuerpo o escala a un determinado Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, y por su antigüedad en el mismo. Dentro de ellas están comprendidas los componentes de sueldo y trienios de las pagas extraordinarias.","Las que retribuyen al funcionario según la adscripción de su cuerpo o escala a un determinado Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, y por su antigüedad en el mismo. Dentro de ellas están comprendidas las que retribuyen las características de los puestos de trabajo o la carrera profesional.","Las que retribuyen al funcionario según la adscripción de su cuerpo o escala a un determinado Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, y por su antigüedad en el mismo. Dentro de ellas están comprendidas las que retribuyen el desempeño, rendimiento o resultados alcanzados por el funcionario.","Las que retribuyen las características de los puestos de trabajo, la carrera profesional o el desempeño, rendimiento o resultados alcanzados por el funcionario."],"a":0},{"id":182,"q":"A los efectos del texto refundido de la Ley del Estatuto Básico del Empleado Público, se entiende por negociación colectiva:","o":["La facultad de elegir representantes y constituir órganos unitarios a través de los cuales se instrumente la interlocución entre las Administraciones Públicas y sus empleados.","El derecho a participar, a través de las organizaciones sindicales, en los órganos de control y seguimiento de las entidades u organismos que legalmente se determine.","El derecho a negociar la determinación de condiciones de trabajo de los empleados de la Administración Pública.","El derecho a negociar las decisiones de las Administraciones Públicas que afecten a sus potestades de organización."],"a":2},{"id":183,"q":"Según el texto refundido de la Ley del Estatuto Básico del Empleado Público, será objeto de negociación, en su ámbito respectivo y en relación con las competencias de cada Administración pública y con el alcance que legalmente proceda en cada caso, la materia siguiente:","o":["La regulación del ejercicio de los derechos de los ciudadanos y de los usuarios de los servicios públicos, así como el procedimiento de formación de los actos y disposiciones administrativas.","La determinación de condiciones de trabajo del personal directivo.","La regulación y determinación concreta, en cada caso, de los sistemas, criterios, órganos y procedimientos de acceso al empleo público y la promoción profesional.","La determinación y aplicación de las retribuciones complementarias de los funcionarios."],"a":3},{"id":184,"q":"Señale la respuesta correcta respecto a los permisos de los funcionarios públicos:","o":["Por razones de guarda legal, cuando el funcionario tenga el cuidado directo de algún menor de dieciséis años, de persona mayor que requiera especial dedicación, o de una persona con discapacidad que no desempeñe actividad retribuida, tendrá derecho a la reducción de su jornada de trabajo, con la disminución de sus retribuciones que corresponda.","Por ser preciso atender el cuidado de un familiar de primer grado, el funcionario tendrá derecho a solicitar una reducción de hasta el cincuenta por ciento de la jornada laboral, con la disminución de sus retribuciones que corresponda, por razones de enfermedad muy grave y por el plazo máximo de un mes.","Por accidente o enfermedad graves, hospitalización o intervención quirúrgica sin hospitalización que precise de reposo domiciliario del cónyuge, pareja de hecho o parientes hasta el primer grado por consanguinidad o afinidad, así como de cualquier otra persona distinta de las anteriores que conviva con el funcionario o funcionaria en el mismo domicilio y que requiera el cuidado efectivo de aquella, cinco días hábiles.","Por matrimonio o registro o constitución formalizada por documento público de pareja de hecho, diez días."],"a":2},{"id":185,"q":"Señale la respuesta correcta respecto a los permisos por motivos de conciliación de la vida personal, familiar y laboral, por razón de violencia de género o de violencia sexual y para las víctimas de terrorismo y sus familiares directos:","o":["Permiso por nacimiento para la madre biológica: tendrá una duración de diecinueve semanas. En el supuesto de monoparentalidad, por existir una única persona progenitora, el permiso será de treinta y ocho semanas.","Permiso del progenitor diferente de la madre biológica por nacimiento, guarda con fines de adopción, acogimiento o adopción de un hijo o hija: tendrá una duración de doce semanas.","Permiso por razón de violencia de género o de violencia sexual sobre la mujer funcionaria: las faltas de asistencia de las funcionarias víctimas de violencia de género o de violencia sexual, totales o parciales, tendrán la consideración de justificadas por el tiempo y en las condiciones en que así lo determinen los servicios sociales de atención o de salud según proceda.","Permiso parental para el cuidado de hijo, hija o menor acogido por tiempo no superior a un año, hasta el momento en que el menor cumpla ocho años: no tendrá carácter retribuido y tendrá una duración superior a ocho semanas, continuas o discontinuas, podrá disfrutarse a tiempo completo, o en régimen de jornada a tiempo parcial, cuando las necesidades del servicio lo permitan y conforme a los términos que reglamentariamente se establezcan."],"a":2},{"id":186,"q":"El Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa es:","o":["De obligado cumplimiento por todos las y los empleados públicos forales.","De carácter voluntario y de recomendación ética.","De obligado cumplimiento para las y los empleados públicos forales nombrados por libre designación y de carácter voluntario para el resto de empleados públicos forales.","De obligado cumplimiento únicamente respecto a cuestiones relacionadas con la contratación pública."],"a":0},{"id":187,"q":"Los Valores Éticos a los que han de ajustar su conducta profesional las y los empleados públicos forales son los siguientes:","o":["Integridad, ejemplaridad, honestidad y desinterés, parcialidad y subjetividad, excelencia profesional, eficiencia y respeto.","Integridad, ejemplaridad, honestidad y desinterés, imparcialidad y objetividad, excelencia profesional, eficiencia y respeto.","Integridad, ejemplaridad, honestidad y desinterés, parcialidad y subjetividad, excelencia profesional y celeridad.","Integridad, ejemplaridad, discreción y confidencialidad, imparcialidad y objetividad, excelencia profesional, eficiencia y respeto."],"a":1},{"id":188,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, la integridad es:","o":["La razón existencial de la institución del empleo público foral, cuya actuación profesional debe estar alejada de influencias y orientaciones políticas o de otro carácter.","Que el empleado público foral dirija sus actuaciones, de forma veraz y transparente, exclusivamente hacia el objetivo del pleno cumplimiento del interés público y de los intereses de la ciudadanía guipuzcoana en su conjunto.","Un valor sustantivo para el servicio público, la buena gestión y el fortalecimiento de las instituciones forales.","La conducta profesional del empleado público foral, que estará guiada por un comportamiento ejemplar, en tanto que las buenas prácticas de las y los empleados públicos favorecen el cambio de la cultura cívica y la interiorización social de las normas."],"a":2},{"id":189,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, la honestidad y desinterés consiste en:","o":["La razón existencial de la institución del empleo público foral, cuya actuación profesional debe estar alejada de influencias y orientaciones políticas o de otro carácter.","Que el empleado público foral dirija sus actuaciones, de forma veraz y transparente, exclusivamente hacia el objetivo del pleno cumplimiento del interés público y de los intereses de la ciudadanía guipuzcoana en su conjunto.","Un valor sustantivo para el servicio público, la buena gestión y el fortalecimiento de las instituciones forales.","La conducta profesional del empleado público foral, que estará guiada por un comportamiento ejemplar, en tanto que las buenas prácticas de las y los empleados públicos favorecen el cambio de la cultura cívica y la interiorización social de las normas."],"a":1},{"id":190,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, la imparcialidad es:","o":["La razón existencial de la institución del empleo público foral, cuya actuación profesional debe estar alejada de influencias y orientaciones políticas o de otro carácter.","Que el empleado público foral dirija sus actuaciones, de forma veraz y transparente, exclusivamente hacia el objetivo del pleno cumplimiento del interés público y de los intereses de la ciudadanía guipuzcoana en su conjunto.","Un valor sustantivo para el servicio público, la buena gestión y el fortalecimiento de las instituciones forales.","La conducta profesional del empleado público foral, que estará guiada por un comportamiento ejemplar, en tanto que las buenas prácticas de las y los empleados públicos favorecen el cambio de la cultura cívica y la interiorización social de las normas."],"a":0},{"id":191,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, la gestión de los recursos y la gestión económico-financiera de las y los empleados públicos forales estarán imbuidas por:","o":["La atención a la ciudadanía.","La eficiencia.","La transparencia.","La celeridad en la toma de decisiones."],"a":1},{"id":192,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, la norma de conducta “en horas y espacios de trabajo, harán un uso razonable y ético de sus dispositivos móviles personales así como de las redes sociales o Internet para uso exclusivamente privado” corresponde al siguiente valor ético:","o":["Integridad.","Ejemplaridad.","Imparcialidad y objetividad.","Respeto."],"a":1},{"id":193,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, la norma de conducta “las y los empleados públicos forales no aceptarán ningún regalo, invitación, viajes, comidas o compensación económica por impartición de conferencias o participación en medios de comunicación siempre que se trate de actividades vinculadas exclusivamente con el ejercicio de sus funciones propias de su puesto de trabajo” corresponde al siguiente valor ético:","o":["Ejemplaridad.","Eficiencia.","Excelencia profesional.","Honestidad y desinterés."],"a":3},{"id":194,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, los principios de buena gestión son los siguientes:","o":["Transparencia, apertura de datos, cultura de gestión e innovación, promoción del uso del euskera y responsabilidad profesional.","Integridad, ejemplaridad, honestidad y desinterés, imparcialidad y objetividad, excelencia profesional, eficiencia y respeto.","Transparencia, integridad, cultura de gestión e innovación, promoción del uso del euskera y excelencia profesional.","Integridad, ejemplaridad, discreción y confidencialidad, imparcialidad y objetividad, excelencia profesional, eficiencia y respeto."],"a":0},{"id":195,"q":"Según el Código Ético y de Buena Gestión del Empleo Público Foral de Gipuzkoa, ¿cuál de las siguientes normas de actuación profesional en el ámbito de la buena gestión está relacionada con la responsabilidad profesional?","o":["Las y los empleados públicos forales desarrollarán en su actividad profesional una cultura de gestión que conlleve mayor implicación en los proyectos, creatividad e iniciativa, así como el impulso de prácticas de innovación en el ámbito de lo público.","Las y los empleados públicos forales actuarán con especial diligencia garantizando respuestas rápidas, efectivas y motivadas, cuando se demande a la Administración Foral información pública por parte de la ciudadanía y de sus entidades, ponderando en cada caso los límites existentes, los derechos en juego e interpretando de forma restrictiva las causas de inadmisión y aquellos límites, con el fin de favorecer el control de la actividad pública por la ciudadanía.","En la gestión cotidiana de su actividad profesional, las y los empleados públicos forales trabajarán a través de las metas y objetivos enmarcados en el Plan Estratégico de gestión de cada mandato, así como mediante el cumplimiento de los indicadores establecidos para poder evaluar los resultados de su gestión.","En su actividad profesional utilizarán preferentemente el euskera tanto oralmente como por escrito, salvo en aquellos actos o relaciones en los que quienes sean sus interlocutores no tengan un conocimiento suficiente de la lengua vasca."],"a":2},{"id":196,"q":"Según la Ley 10/1982, ¿qué consideración tiene el euskera?","o":["Es la lengua secundaria de la Comunidad Autónoma.","Es la lengua propia del Pueblo Vasco.","Es una lengua de uso meramente literario.","Es la lengua oficial única del territorio."],"a":1},{"id":197,"q":"Según la Ley 10/1982, ¿cómo califica el artículo 3 el estatus del euskera en la Comunidad Autónoma?","o":["Lengua cooficial opcional.","Lengua oficial, al igual que el castellano.","Lengua de interés cultural preferente.","Lengua administrativa exclusiva."],"a":1},{"id":198,"q":"¿Qué derecho reconoce el artículo 5 de la Ley 10/1982 a todos los ciudadanos del País Vasco?","o":["El derecho a conocer y usar las dos lenguas oficiales.","El derecho a recibir subvenciones para aprender euskera.","El derecho a elegir una tercera lengua en la Administración.","El derecho a ser atendido en cualquier lengua que elijan en la Administración."],"a":0},{"id":199,"q":"Según la Ley 10/1982, ¿cómo debe ir redactado todo acto en el que intervengan los poderes públicos sitos en la Comunidad Autónoma del País Vasco, así como las notificaciones y comunicaciones administrativas?","o":["Deberán ir redactados en forma euskera, salvo que los interesados privados elijan expresamente la utilización de otro idioma.","Deberán ir redactados en forma castellano, salvo que los interesados privados elijan expresamente la utilización del euskera.","Deberán ir redactados en forma bilingüe, salvo que los interesados privados elijan expresamente la utilización de una de las lenguas oficiales de la Comunidad Autónoma.","Deberán ir redactados en forma bilingüe, en todo caso."],"a":2},{"id":200,"q":"Según la Ley 10/1982, en sus relaciones con la Administración de Justicia:","o":["Todo ciudadano deberá utilizar la lengua oficial elegida por los jueces.","Todo ciudadano podrá utilizar la lengua oficial de su elección, aunque se le podrá exigir realizar traducciones en caso de ser necesarios.","Todo ciudadano podrá utilizar la lengua oficial de su elección, sin que se le pueda exigir traducción alguna, salvo en determinadas materias donde por su dificultad resulte necesario exigir la traducción de escritos y documentos de carácter técnico.","Todo ciudadano podrá utilizar la lengua oficial de su elección, sin que se le pueda exigir traducción alguna."],"a":3},{"id":201,"q":"Según la Ley 10/1982, señale la respuesta correcta:","o":["Los impresos o modelos que hayan de utilizarse por los poderes públicos y privados en la Comunidad Autónoma del País Vasco, deberán estar redactados en forma bilingüe.","Los impresos o modelos oficiales que hayan de utilizarse por los poderes públicos en la Comunidad Autónoma del País Vasco, deberán estar redactados en forma bilingüe.","Los impresos o modelos que hayan de utilizarse por los poderes públicos y privados en la Comunidad Autónoma del País Vasco, podrán estar redactados, exclusivamente en euskera.","Los impresos o modelos oficiales que hayan de utilizarse por los poderes públicos en la Comunidad Autónoma del País Vasco, podrán estar redactados exclusivamente en castellano."],"a":1},{"id":202,"q":"¿Qué reconoce el artículo 15 de la Ley 10/1982 a todos los alumnos del País Vasco?","o":["El derecho a estudiar en una lengua extranjera de su elección.","La obligación de cursar todas las asignaturas en euskera.","El derecho a recibir la enseñanza tanto en euskera como en castellano en los diversos niveles educativos.","El derecho a no ser evaluado en las asignaturas de lengua."],"a":2},{"id":203,"q":"Según la Ley 10/1982, los centros privados subvencionados con fondos públicos que impartan enseñanzas regladas tomando como base una lengua no oficial en la Comunidad:","o":["Impartirán como asignaturas obligatorias el euskera y el castellano.","Impartirán como asignaturas obligatorias el euskera o el castellano.","Impartirán como asignaturas optativas el euskera y el castellano.","Impartirán como asignaturas optativas el euskera o el castellano."],"a":0},{"id":204,"q":"Según la Ley 10/1982, ¿qué promoverá el Gobierno en los medios de comunicación de la Comunidad Autónoma?","o":["El uso del castellano para garantizar la difusión exterior.","El empleo exclusivo del euskera a fin de garantizar la equiparación de ambas lenguas.","El empleo preferente del euskera a fin de garantizar la equiparación de ambas lenguas.","La obligatoriedad de que todos los periodistas sean bilingües."],"a":2},{"id":205,"q":"Según la Ley 10/1982, ¿en qué ámbitos de la vida social deben los poderes públicos fomentar el uso del euskera?","o":["Únicamente en el ámbito laboral y administrativo.","En las actividades mercantiles, culturales, asociativas, deportivas, religiosas y cualesquiera otras.","En las actividades mercantiles, culturales, asociativas, deportivas, religiosas y cualesquiera otras en aquellas localidades donde el euskera sea la lengua mayoritaria.","En las actividades mercantiles, culturales, asociativas, deportivas, religiosas y cualesquiera otras en aquellas localidades donde el euskera sea la lengua minoritaria."],"a":1},{"id":206,"q":"Según la Ley 11/2022, ¿a qué están obligadas las administraciones públicas vascas respecto a las lenguas oficiales?","o":["A dar prioridad al euskera en las relaciones externas.","A dar prioridad al euskera en las relaciones internas.","A utilizar el castellano únicamente cuando el ciudadano lo solicite.","A garantizar en sus relaciones, tanto internas como externas, la utilización de ambas."],"a":3},{"id":207,"q":"Según la Ley 11/2022, ¿qué instrumento deben aprobar las administraciones públicas vascas para fijar sus objetivos y medidas lingüísticas?","o":["Un reglamento orgánico municipal de lenguas.","Un instrumento de planificación lingüística.","Un catálogo de puestos de bilingüismo obligatorio.","Un protocolo de uso interno del euskera."],"a":1},{"id":208,"q":"Según la Ley 11/2022, todos los puestos de trabajo existentes en las administraciones públicas vascas, sus instituciones y organismos, incluidos aquellos de naturaleza temporal o coyuntural:","o":["Tendrán asignado su correspondiente perfil lingüístico, determinado según las características y necesidades comunicativas atribuidas a dichos puestos de trabajo y a las destrezas lingüísticas exigibles a dicho fin.","Tendrán asignado su correspondiente perfil lingüístico, determinado según los conocimientos acreditados por la persona ocupante del puesto.","Tendrán asignado su correspondiente perfil lingüístico, determinado según el nivel de conocimiento de euskera de la población en la que tenga sede la administración pública correspondiente.","Tendrán asignado un idioma de trabajo, que podrá ser el euskera o el castellano."],"a":0},{"id":209,"q":"La asignación del perfil lingüístico a cada uno de los puestos de trabajo existentes en las administraciones públicas vascas, sus instituciones y organismos, así como la de su fecha de preceptividad:","o":["Se efectuarán por el departamento del Gobierno Vasco competente en materia de política lingüística.","Se efectuarán por sus respectivos órganos de gobierno, previo informe preceptivo de los departamentos de las diputaciones forales competentes en materia de política lingüística.","Se efectuarán por sus respectivos órganos de gobierno, previo informe preceptivo del departamento del Gobierno Vasco competente en materia de política lingüística.","Se efectuarán por sus respectivos órganos de gobierno, previo informe preceptivo y vinculante de los departamentos de las diputaciones forales competentes en materia de política lingüística."],"a":2},{"id":210,"q":"Según la Ley 11/2022, ¿dónde deben quedar incorporados el perfil lingüístico y la fecha de preceptividad de cada uno de los puestos de trabajo existentes en las administraciones públicas vascas?","o":["En el expediente del empleado público que ocupa cada puesto.","En las relaciones de puestos de trabajo, así como en los instrumentos complementarios recogidos en la ley.","En el Plan General de Normalización del Gobierno Vasco.","En los Planes Generales de Normalización del Gobierno Vasco y de las diputaciones forales."],"a":1},{"id":211,"q":"Según la Ley 11/2022, en los procesos selectivos para el acceso al servicio de las administraciones públicas vascas, cuando el conocimiento del euskera sea mérito:","o":["La puntuación otorgada al conocimiento del euskera representará un porcentaje que no podrá ser en ningún caso superior al diez por ciento de la puntuación máxima alcanzable en el conjunto del proceso selectivo.","La puntuación otorgada al conocimiento del euskera representará un porcentaje que no podrá ser en ningún caso superior al veinte por ciento de la puntuación máxima alcanzable en el conjunto del proceso selectivo.","La puntuación otorgada al conocimiento del euskera representará un porcentaje que no podrá ser en ningún caso superior al diez por ciento de la puntuación máxima alcanzable en la fase de concurso.","La puntuación otorgada al conocimiento del euskera representará un porcentaje que no podrá ser en ningún caso superior al veinte por ciento de la puntuación máxima alcanzable en la fase de concurso."],"a":0},{"id":212,"q":"Según la Ley 11/2022, el único organismo habilitado para la acreditación de perfiles","o":["El Instituto de Alfabetización y Reeuskaldunización de Adultos (HABE).","El Instituto Vasco de Administración Pública.","La Escuela Oficial de Idiomas.","El Gobierno Vasco."],"a":1},{"id":213,"q":"Según el Decreto 19/2024, de normalización del uso del euskera en el Sector Público Vasco, el perfil lingüístico determina:","o":["El nivel de competencia lingüística en comprensión oral en euskera necesario para la provisión y desempeño del puesto de trabajo.","El nivel de competencia lingüística en comprensión escrita en euskera necesario para la provisión y desempeño del puesto de trabajo.","El conjunto de los niveles de competencia lingüística en euskera y castellano necesarios para la provisión y desempeño del puesto de trabajo.","El conjunto de los niveles de competencia lingüística en euskera necesarios para la provisión y desempeño del puesto de trabajo."],"a":3},{"id":214,"q":"Según el Decreto 19/2024, de normalización del uso del euskera en el Sector Público Vasco, cuando la fecha de preceptividad esté vencida en la relación de puestos de trabajo de la entidad:","o":["El cumplimiento del perfil lingüístico se constituirá como exigencia obligatoria para el acceso y desempeño del correspondiente puesto de trabajo.","El cumplimiento del perfil lingüístico se constituirá como exigencia obligatoria para el acceso y desempeño del correspondiente puesto de trabajo en el plazo de un año desde la fecha de preceptividad.","El cumplimiento del perfil lingüístico se constituirá como exigencia obligatoria para el acceso y desempeño del correspondiente puesto de trabajo en el plazo de dos años desde la fecha de preceptividad.","El cumplimiento del perfil lingüístico dejará de ser exigencia obligatoria para el acceso y desempeño del correspondiente puesto de trabajo."],"a":0},{"id":215,"q":"Según el Decreto 19/2024, de normalización del uso del euskera en el Sector Público Vasco, se reconoce a todo el personal al servicio de las entidades del sector público vasco el derecho a:","o":["Utilizar como único idioma de trabajo el euskera.","Utilizar el idioma que mejor domine en las relaciones con la ciudadanía.","Recibir formación en euskera.","Recibir formación de euskera al menos durante 5 horas semanales."],"a":2},{"id":216,"q":"Según el Decreto 19/2024, de normalización del uso del euskera en el Sector Público Vasco, el índice de obligado cumplimiento se determinará de la siguiente forma:","o":["(Euskaldunes/2) + Cuasi euskaldunes.","Euskaldunes + (Cuasi euskaldunes/2).","Euskaldunes + (Cuasi euskaldunes*2).","(Euskaldunes*2) + Cuasi euskaldunes."],"a":1},{"id":217,"q":"Según el Decreto 19/2024, de normalización del uso del euskera en el Sector Público Vasco, en los procesos de selección y provisión de puestos de trabajo que tengan asignado el perfil lingüístico C2 y cuya fecha de preceptividad se encuentre vencida, en caso de no acreditarse este por ninguna de las personas candidatas:","o":["Se aplicará a dicho puesto el perfil lingüístico C1 a los únicos efectos de cobertura en tal convocatoria de selección o provisión.","Se diferirá la fecha de preceptividad de los puestos que queden vacantes, para garantizar la cobertura de las mismas.","Se modificará el perfil lingüístico de dicho puesto del perfil lingüístico C2 al perfil lingüístico C1.","No se podrán cubrir los puestos con el perfil lingüístico C2 y deberá convocarse un nuevo proceso de selección y provisión de puestos de trabajo en un plazo improrrogable de 6 meses."],"a":0},{"id":218,"q":"Cuando la acreditación del perfil lingüístico asignado a un puesto de trabajo sea preceptiva:","o":["La acreditación de dicho perfil o de perfiles inferiores o superiores se valorará como mérito hasta un límite del veinte por ciento.","La acreditación de dicho perfil o de perfiles inferiores o superiores se valorará como mérito hasta un límite del quince por ciento.","La acreditación de dicho perfil o de perfiles inferiores o superiores se valorará como mérito hasta un límite del diez por ciento.","La acreditación de dicho perfil o de perfiles inferiores o superiores no se valorará como mérito."],"a":3},{"id":219,"q":"Para establecer la valoración que, como mérito, haya de otorgarse al conocimiento del euskera en cada convocatoria de procesos de selección o de provisión se tomará como base la puntuación máxima alcanzable en el conjunto del proceso, de modo que la puntuación otorgada al conocimiento del euskera representará un porcentaje que deberá situarse en los siguientes umbrales, no pudiendo ser inferior ni superior:","o":["En perfiles simétricos, comprensión y expresión escrita y comprensión y expresión oral B1 entre el 5 % y el 10 %.","En perfiles simétricos, comprensión y expresión escrita y comprensión y expresión oral B2 entre el 11 % y el 15 %.","En perfiles simétricos, comprensión y expresión escrita y comprensión y expresión oral C1 entre el 16 % y el 20 %.","En perfiles simétricos, comprensión y expresión escrita y comprensión y expresión oral C2 entre el 21 % y el 25 %."],"a":0},{"id":220,"q":"Estarán exentos del cumplimiento del régimen general de preceptividad de los perfiles lingüísticos en relación con el puesto de trabajo del que son titulares:","o":["Las personas que superen la edad de 40 años al inicio de cada período de planificación en el que se asigne la fecha de preceptividad al puesto de trabajo del que son titulares, previa conformidad de la persona interesada.","Las personas cuyo nivel de estudios realizados no alcanzara los de Bachiller Elemental, Educación General Básica o Educación Secundaria Obligatoria, ni otros que, en el futuro, pudieran sustituir a estos, prescindiendo de las equivalencias y convalidaciones que contemple el ordenamiento jurídico a otros fines respecto al Certificado de Escolaridad.","Las personas con discapacidad mediante los programas vigentes de formación y capacitación lingüística de personas adultas.","Las personas que declaren carencia manifiesta y contrastada de las destrezas aptitudinales necesarias en el proceso de aprendizaje del idioma mediante los programas de formación y capacitación lingüística de personas adultas."],"a":1},{"id":221,"q":"¿Cuál es el objeto de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres?","o":["Establecer los principios generales que han de presidir la actuación de los poderes públicos y privados en materia de igualdad de mujeres y hombres, así como regular un conjunto de medidas dirigidas a promover y garantizar la igualdad de oportunidades y trato de mujeres y hombres exclusivamente en el ámbito laboral.","Establecer los principios generales que han de presidir la actuación de los poderes públicos en materia de igualdad de mujeres y hombres, así como regular un conjunto de medidas dirigidas a promover y garantizar la igualdad de oportunidades y trato de mujeres y hombres en todos los ámbitos de la vida y, en particular, a promover el empoderamiento de las mujeres, su autonomía y el fortalecimiento de su posición social, económica y política al objeto de eliminar la desigualdad estructural y todas las formas de discriminación por razón de sexo, incluida la violencia machista contra las mujeres.","Establecer los principios generales que han de presidir la actuación de los poderes públicos en materia de igualdad de mujeres y hombres, así como regular un conjunto de medidas dirigidas a promover y garantizar la igualdad de oportunidades y trato de mujeres y hombres en todos los ámbitos de la vida y, en particular, a promover el empoderamiento de las mujeres, su autonomía y el fortalecimiento de su posición social, económica y política al objeto de reducir la desigualdad estructural y todas las formas de discriminación por razón de sexo, incluida la violencia machista contra las mujeres.","Establecer los principios generales que han de presidir la actuación de los poderes públicos y privados en materia de igualdad de mujeres y hombres, así como regular un conjunto de medidas dirigidas a promover y garantizar la igualdad de oportunidades y trato de mujeres y hombres en todos los ámbitos de la vida y, en particular, a promover el empoderamiento de las mujeres, su autonomía y el fortalecimiento de su posición social, económica y política al objeto de eliminar la desigualdad estructural y todas las formas de discriminación por razón de sexo, incluida la violencia machista contra las mujeres."],"a":1},{"id":222,"q":"¿Cuál es el fin último de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres?","o":["Lograr una sociedad igualitaria y libre de violencia machista en la que todas las personas sean libres, en el ámbito público, para desarrollar sus capacidades personales y tomar decisiones sin las limitaciones impuestas por los roles tradicionales en función del género, y en la que se tengan en cuenta, valoren y potencien por igual las distintas conductas, aspiraciones y necesidades de mujeres y hombres.","Lograr una sociedad igualitaria y libre de violencia machista en la que todas las personas sean libres, en el ámbito privado, para desarrollar sus capacidades personales y tomar decisiones sin las limitaciones impuestas por los roles tradicionales en función del género, y en la que se tengan en cuenta, valoren y potencien por igual las distintas conductas, aspiraciones y necesidades de mujeres y hombres.","Lograr una sociedad igualitaria y libre de violencia machista en la que todas las personas sean libres, tanto en el ámbito público como en el privado, para desarrollar sus capacidades personales y tomar decisiones sin las limitaciones impuestas por los roles tradicionales en función del género, y en la que se tengan en cuenta, valoren y potencien por igual las distintas conductas, aspiraciones y necesidades de mujeres y hombres.","Lograr una reducción importante de la violencia machista y fomentar una sociedad igualitaria."],"a":2},{"id":223,"q":"La Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres es de aplicación:","o":["A todas las administraciones públicas vascas, con las salvedades que a lo largo de ella se establezcan.","Solo al Gobierno Vasco.","Solo a entidades privadas del País Vasco.","Solo a los Ayuntamientos de la Comunidad Autónoma del País Vasco."],"a":0},{"id":224,"q":"Los principios generales del artículo 3 de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres son de aplicación:","o":["Únicamente a las administraciones públicas vascas con sus respectivas administraciones institucionales y demás entes instrumentales dependientes o adscritos a ellas.","A todos los poderes públicos vascos.","A todos los poderes públicos vascos, salvo el Parlamento Vasco y las Juntas generales de los territorios históricos.","A todos los poderes públicos vascos, salvo el Ararteko y el Tribunal Vasco de Cuentas Públicas."],"a":1},{"id":225,"q":"A las entidades privadas que suscriban contratos o convenios de colaboración con los poderes públicos vascos:","o":["No les será exigible durante ningún momento el cumplimiento de los principios generales del artículo 3 de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, aunque se valorará su cumplimiento en el momento de suscribir los contratos o convenios de colaboración.","Les será exigible en un plazo de tres años desde el inicio de su relación con el poder público correspondiente el cumplimiento de los principios generales del artículo 3 de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres.","Les será exigible únicamente en el momento de la suscripción del contrato o convenio de colaboración el cumplimiento de los principios generales del artículo 3 de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres.","Les será exigible durante el tiempo y materia sobre la que verse su relación con el poder público correspondiente el cumplimiento de los principios generales del artículo 3 de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres."],"a":3},{"id":226,"q":"¿Cuál de los siguientes NO es un principio general del artículo 3 de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres?","o":["Igualdad de trato.","Neutralidad institucional.","Respeto a la diversidad y a la diferencia.","Eliminación de roles y estereotipos en función del género."],"a":1},{"id":227,"q":"¿Cuál de los siguientes NO es un principio general del artículo 3 de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres?","o":["Igualdad de trato.","Igualdad de oportunidades.","Prevención, atención y erradicación de la violencia machista contra las mujeres.","Respeto a la homogeneidad y a la igualdad."],"a":3},{"id":228,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, cuando una persona sea, haya sido o pudiera ser tratada de manera menos favorable que otra en situación análoga por razón de su sexo o de circunstancias directamente relacionadas con el sexo, como el embarazo o la maternidad:","o":["Existirá discriminación indirecta.","Existirá discriminación indirecta, salvo que dicho acto jurídico, criterio o práctica resulte adecuada y necesaria, y pueda justificarse con criterios objetivos que no estén relacionados con el sexo.","Existirá discriminación directa únicamente cuando se demuestre un perjuicio económico.","Existirá discriminación directa."],"a":3},{"id":229,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, sin perjuicio de su posible tipificación como delito, el acoso sexual:","o":["Tiene la consideración de discriminación directa por razón de sexo.","Tiene la consideración de discriminación indirecta por razón de sexo.","No tiene la consideración de discriminación por razón de sexo.","Puede tener la consideración de discriminación directa por razón de sexo en determinados casos."],"a":0},{"id":230,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, cuando un acto jurídico, criterio o práctica aparentemente neutra perjudique a una proporción sustancialmente mayor de personas de un mismo sexo:","o":["Existirá discriminación indirecta.","Existirá discriminación indirecta, salvo que dicho acto jurídico, criterio o práctica resulte adecuada y necesaria, y pueda justificarse con criterios objetivos que no estén relacionados con el sexo.","Existirá discriminación directa únicamente cuando se demuestre un perjuicio económico.","Existirá discriminación directa."],"a":1},{"id":231,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, las medidas que, aunque planteen un tratamiento diferente para las mujeres y los hombres, tienen una justificación objetiva y razonable, entre las que se incluyen aquellas que se fundamentan en la acción positiva para las mujeres, en la necesidad de una protección especial de los sexos por motivos biológicos, o en la promoción de la incorporación de los hombres al trabajo doméstico y de cuidado de las personas y al trabajo a favor de la igualdad de trato y oportunidades:","o":["No se considerarán constitutivas de discriminación por razón de sexo.","Se considerarán constitutivas de discriminación directa por razón de sexo.","Se considerarán constitutivas de discriminación indirecta por razón de sexo.","Se considerarán constitutivas de discriminación indirecta por razón de sexo si así se recoge expresamente en la norma reguladora de las medidas a adoptar."],"a":0},{"id":232,"q":"La Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres establece que los poderes públicos vascos:","o":["Deben adoptar las medidas oportunas para garantizar el ejercicio efectivo por parte de mujeres y hombres, en condiciones de igualdad, de los derechos políticos, civiles, económicos, laborales, sociales, culturales, medioambientales y del resto de derechos fundamentales que puedan ser reconocidos en las normas, incluido el control y acceso al poder y a los recursos y beneficios económicos y sociales.","Pueden adoptar las medidas oportunas para garantizar el ejercicio efectivo por parte de mujeres y hombres, en condiciones de igualdad, de los derechos políticos, civiles, económicos, laborales, sociales, culturales, medioambientales y del resto de derechos fundamentales que puedan ser reconocidos en las normas, incluido el control y acceso al poder y a los recursos y beneficios económicos y sociales.","Deben adoptar las medidas oportunas para fomentar el ejercicio efectivo por parte de mujeres y hombres, en condiciones de igualdad, de los derechos políticos, civiles, económicos, laborales, sociales, culturales, medioambientales y del resto de derechos fundamentales que puedan ser reconocidos en las normas, incluido el control y acceso al poder y a los recursos y beneficios económicos y sociales.","Pueden adoptar las medidas oportunas para fomentar el ejercicio efectivo por parte de mujeres y hombres, en condiciones de igualdad, de los derechos políticos, civiles, económicos, laborales, sociales, culturales, medioambientales y del resto de derechos fundamentales que puedan ser reconocidos en las normas, incluido el control y acceso al poder y a los recursos y beneficios económicos y sociales."],"a":0},{"id":233,"q":"En cuanto a la prevención, atención y erradicación de la violencia machista contra las mujeres, señale la respuesta correcta:","o":["Los poderes públicos vascos integrarán de forma transversal en sus políticas y acciones el objetivo de prevenir, atender y erradicar la violencia machista contra las mujeres en sus diferentes formas.","Los poderes públicos vascos integrarán de forma transversal en sus políticas y acciones el objetivo de prevenir, atender y reducir la violencia machista contra las mujeres en sus diferentes formas.","Los poderes públicos vascos integrarán de forma transversal en sus políticas y acciones el objetivo de atender y reducir la violencia machista contra las mujeres en sus diferentes formas.","Los poderes públicos vascos integrarán de forma transversal en sus políticas y acciones el objetivo de prevenir y reducir la violencia machista contra las mujeres en sus diferentes formas."],"a":0},{"id":234,"q":"Señale la respuesta INCORRECTA:","o":["Los poderes públicos pondrán los medios necesarios para que el proceso hacia la igualdad de sexos se realice respetando tanto la diversidad y las diferencias existentes entre mujeres y hombres en cuanto a su biología, condiciones de vida, aspiraciones y necesidades, como la diversidad y diferencias existentes dentro de los propios grupos de mujeres y de hombres.","Será una prioridad de los poderes públicos vascos la atención integral, recuperación y reparación de las víctimas de la violencia machista contra las mujeres.","Existirá discriminación indirecta cuando un acto jurídico, criterio o práctica aparentemente neutra perjudique a una proporción sustancialmente mayor de personas de un mismo sexo, salvo que dicho acto jurídico, criterio o práctica resulte adecuada y necesaria, y pueda justificarse con criterios objetivos que no estén relacionados con el sexo.","Se considerarán constitutivas de discriminación por razón de sexo las medidas que planteen un tratamiento diferente para las mujeres y los hombres, aunque tengan una justificación objetiva y razonable, entre las que se incluyen aquellas que se fundamentan en la acción positiva para las mujeres, en la necesidad de una protección especial de los sexos por motivos biológicos, o en la promoción de la incorporación de los hombres al trabajo doméstico y de cuidado de las personas y al trabajo a favor de la igualdad de trato y oportunidades."],"a":3},{"id":235,"q":"A efectos de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres se entiende por integración de la perspectiva de género:","o":["La consideración sistemática de las diferentes situaciones, condiciones, aspiraciones y necesidades de mujeres y hombres, incorporando objetivos y actuaciones específicas dirigidas a eliminar las desigualdades y promover la igualdad en todas las políticas y acciones, a todos los niveles y en la fase de planificación.","La consideración sistemática de las diferentes situaciones, condiciones, aspiraciones y necesidades de mujeres y hombres, incorporando objetivos y actuaciones específicas dirigidas a eliminar las desigualdades y promover la igualdad en todas las políticas y acciones, a todos los niveles y en la fase de ejecución.","La consideración sistemática de las diferentes situaciones, condiciones, aspiraciones y necesidades de mujeres y hombres, incorporando objetivos y actuaciones específicas dirigidas a eliminar las desigualdades y promover la igualdad en todas las políticas y acciones, en la fase de evaluación.","La consideración sistemática de las diferentes situaciones, condiciones, aspiraciones y necesidades de mujeres y hombres, incorporando objetivos y actuaciones específicas dirigidas a eliminar las desigualdades y promover la igualdad en todas las políticas y acciones, a todos los niveles y en todas sus fases de planificación, ejecución y evaluación."],"a":3},{"id":236,"q":"Las medidas específicas y temporales adoptadas por los poderes públicos destinadas a eliminar o reducir las desigualdades de hecho por razón de sexo existentes en los diferentes ámbitos de la vida se consideran:","o":["Eliminación de roles y estereotipos en función del género.","Discriminación directa.","Acción positiva.","Integración de la perspectiva interseccional."],"a":2},{"id":237,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, Señale la respuesta correcta respecto a la eliminación de roles y estereotipos en función del género:","o":["Los poderes públicos vascos podrán promover la eliminación de los roles sociales y estereotipos en función del género sobre los que se asienta la desigualdad entre mujeres y hombres y según los cuales se asigna a las mujeres la responsabilidad del ámbito de lo doméstico y a los hombres la del ámbito público, con una muy desigual valoración y reconocimiento económico y social.","Los poderes públicos vascos podrán promover la eliminación de los roles sociales y estereotipos en función del género sobre los que se asienta la desigualdad entre mujeres y hombres y según los cuales se asigna a los hombres la responsabilidad del ámbito de lo doméstico y a las mujeres la del ámbito público, con una muy desigual valoración y reconocimiento económico y social.","Los poderes públicos vascos deben promover la eliminación de los roles sociales y estereotipos en función del género sobre los que se asienta la desigualdad entre mujeres y hombres y según los cuales se asigna a las mujeres la responsabilidad del ámbito de lo doméstico y a los hombres la del ámbito público, con una valoración y reconocimiento económico y social muy similar.","Los poderes públicos vascos deben promover la eliminación de los roles sociales y estereotipos en función del género sobre los que se asienta la desigualdad entre mujeres y hombres y según los cuales se asigna a las mujeres la responsabilidad del ámbito de lo doméstico y a los hombres la del ámbito público, con una muy desigual valoración y reconocimiento económico y social."],"a":3},{"id":238,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, para promover la consecución de la igualdad real y efectiva de mujeres y hombres:","o":["Los poderes públicos deben desarrollar las políticas públicas necesarias que aseguren la subordinación corporal de todas las personas.","Los poderes públicos deben adoptar las medidas necesarias para reducir de todos los ámbitos de la vida las discriminaciones relacionadas con la identidad sexual o de género y la orientación sexual.","Los poderes públicos deben desarrollar la autodeterminación de todas las personas, en particular las mujeres y, en especial, el ejercicio de sus derechos sexuales y reproductivos, desde una perspectiva integral y multidisciplinar.","Los poderes públicos deben, por un lado, adoptar las medidas necesarias para erradicar de todos los ámbitos de la vida las discriminaciones relacionadas con la identidad sexual o de género y la orientación sexual, así como, por otro lado, desarrollar las políticas públicas necesarias que aseguren la autonomía corporal y la autodeterminación de todas las personas, en particular las mujeres y, en especial, el ejercicio de sus derechos sexuales y reproductivos, desde una perspectiva integral y multidisciplinar."],"a":3},{"id":239,"q":"Por lo que respecta a los órganos pluripersonales, a los efectos de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, se considera que existe una representación equilibrada cuando:","o":["En los órganos de más de seis miembros las personas de cada sexo están representadas al menos al 30 %. En el resto, cuando personas de ambos sexos estén representadas.","En los órganos de más de diez miembros las personas de cada sexo están representadas al menos al 30 %. En el resto, cuando personas de ambos sexos estén representadas.","En los órganos de más de cuatro miembros las personas de cada sexo están representadas al menos al 40 %. En el resto, cuando personas de ambos sexos estén representadas.","En los órganos de más de seis miembros las personas de cada sexo están representadas al menos al 40 %. En el resto, cuando personas de ambos sexos estén representadas."],"a":2},{"id":240,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, señale la respuesta INCORRECTA:","o":["Los poderes públicos vascos tienen la obligación de colaborar y coordinar sus actuaciones en materia de igualdad de mujeres y hombres para que sus intervenciones sean más eficaces y acordes con una utilización racional de los recursos.","Los poderes públicos vascos han de promover la incorporación de la perspectiva de género en las políticas de cooperación para el desarrollo, así como la internacionalización de las políticas de igualdad, a fin de captar e intercambiar conocimiento y recursos y de posicionar de forma destacada al País Vasco en la acción internacional para dar cumplimiento al objetivo global de la agenda internacional de desarrollo sostenible de lograr la igualdad entre los sexos y el empoderamiento de las mujeres.","Los poderes públicos vascos tienen que establecer las condiciones y realizar las adaptaciones necesarias para favorecer el empoderamiento de las mujeres, considerando su homogeneidad.","Los poderes públicos vascos han de adoptar las medidas oportunas para lograr una presencia equilibrada de mujeres y hombres con capacitación, competencia y preparación adecuadas en los distintos ámbitos de toma de decisiones."],"a":2},{"id":241,"q":"De acuerdo con el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, ¿cuál de las siguientes afirmaciones define correctamente el objetivo del empoderamiento de las mujeres?","o":["Se refiere exclusivamente al éxito individual de las mujeres en el ámbito económico para construir economías más fuertes y estables, que permita optimizar el talento y el potencial financiero individual de las mujeres y así corregir ineficiencias históricas, derivando en estructuras financieras más robustas y sistemas económicos capaces de resistir mejor las crisis internacionales.","Es el proceso que las mujeres llevan a cabo para la toma de conciencia individual y colectiva de la situación estructural de desigualdad y discriminación que sufren por el hecho de ser mujeres, y para la adquisición de la competencia, el poder y el control que les permitan tomar decisiones estratégicas sobre sus propias vidas y transformar las estructuras e instituciones que refuerzan y perpetúan la desigualdad y discriminación por razón de género en los distintos ámbitos de la vida.","Es una metodología de trabajo centrada únicamente en identificar y cuestionar las diferencias biológicas entre hombres y mujeres en el ámbito laboral con el objetivo de desmontar los sesgos que justifican la desigualdad de oportunidades. Al examinar rigurosamente qué diferencias son reales y cuáles son construcciones sociales, esta metodología permite separar la capacidad profesional de los prejuicios biológicos, garantizando que el acceso a puestos de liderazgo se base en la competencia y no en suposiciones físicas.","Consiste en garantizar una cuota del 40 % de representación femenina en todas las listas electorales y órganos de gobierno de las administraciones públicas vascas."],"a":1},{"id":242,"q":"¿Qué deben promover los poderes públicos vascos respecto a los hombres según el principio general “Implicación de los hombres” de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres?","o":["La participación exclusiva de los hombres en políticas económicas.","La participación preferente de los hombres en la ejecución de las políticas de igualdad.","La concienciación, responsabilidad, participación e implicación de los hombres a favor de la igualdad.","No existe ningún principio general sobre la implicación de los hombres en la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres."],"a":2},{"id":243,"q":"Según el principio general “Participación” de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, ¿qué deben impulsar los poderes públicos vascos en el desarrollo de las políticas públicas?","o":["La participación exclusiva de las administraciones públicas.","La participación e interlocución de los grupos feministas y de mujeres, de los agentes sociales y de la ciudadanía en su conjunto.","La participación de expertos técnicos.","La participación mayoritaria de las mujeres."],"a":1},{"id":244,"q":"Según el principio general “Innovación, transparencia y rendición de cuentas” de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, los poderes públicos vascos deben:","o":["Frenar la innovación y la mejora continua de las políticas de igualdad hasta que se garantice el cumplimiento de las mismas y garantizar la transparencia y la rendición de cuentas a la ciudadanía sobre cómo se contribuye a la igualdad de mujeres y hombres a través de los recursos públicos.","Fomentar la innovación y la mejora continua de las políticas de igualdad y garantizar la transparencia y la rendición de cuentas a la ciudadanía sobre cómo se contribuye a la igualdad de mujeres y hombres a través de los recursos públicos.","Fomentar la innovación y la mejora continua de las políticas de igualdad y garantizar la transparencia y la rendición de cuentas a la ciudadanía sobre cómo se contribuye a la igualdad de mujeres y hombres a través de los recursos privados.","Fomentar la innovación y la mejora continua de las entidades privadas en relación a las políticas de igualdad y garantizar la transparencia y la rendición de cuentas a los poderes públicos."],"a":1},{"id":245,"q":"En relación al principio general protección de los derechos lingüísticos y promoción del uso del euskera, ¿qué deben asegurar los poderes públicos en el desarrollo de políticas de igualdad?","o":["Que los servicios se presten en la lengua cooficial elegida por la persona interesada.","Que los servicios se presten únicamente en euskera.","Que los servicios se presten únicamente en castellano.","Que los servicios se presten en cualquier lengua elegida por la persona interesada."],"a":0},{"id":246,"q":"¿Cuál es el fin último de la Norma Foral 2/2015, de 9 de marzo, para la igualdad de mujeres y hombres?","o":["Establecer exclusivamente el régimen sancionador en materia de discriminación por razón de sexo.","Garantizar las condiciones necesarias para la consecución de la igualdad real y efectiva de mujeres y hombres en todos sus ámbitos de actuación, a fin de contribuir a la construcción de un modelo de organización social en el Territorio de Gipuzkoa que coloque la sostenibilidad de la vida en el centro de las políticas públicas de la Diputación Foral de Gipuzkoa.","Regular únicamente la estructura interna de la Dirección de Igualdad de la Diputación Foral de Gipuzkoa.","Promover la autonomía de las mujeres exclusivamente en el ámbito laboral y de la empresa privada."],"a":1},{"id":247,"q":"De acuerdo con la Norma Foral 2/2015, de 9 de marzo, para la igualdad de mujeres y hombres, ¿a cuál de las siguientes entidades NO se le aplica esta Norma Foral?","o":["A las fundaciones del sector público foral del Territorio Histórico de Gipuzkoa, que se definan como tal en la normativa que les sea aplicable.","A las sociedades mercantiles forales.","A las empresas privadas que no tengan contratos vigentes con la Administración Foral.","A los organismos autónomos forales y entidades públicas empresariales forales."],"a":2},{"id":248,"q":"De acuerdo con la Norma Foral 2/2015, de 9 de marzo, ¿a qué entidades privadas les son de aplicación los principios generales de igualdad?","o":["A todas las entidades privadas con sede social en el Territorio Histórico de Gipuzkoa.","Únicamente a aquellas entidades privadas que tengan más de 50 trabajadores en plantilla.","A las entidades privadas que suscriban contratos, convenios de colaboración o sean beneficiarias de ayudas o subvenciones de los poderes públicos forales.","Las entidades privadas están exentas de cumplir estos principios, ya que solo afectan al sector público foral."],"a":2},{"id":249,"q":"De acuerdo con la Norma Foral 2/2015, de 9 de marzo, ¿cuál de las siguientes tareas corresponde a la Diputación Foral de Gipuzkoa para garantizar la igualdad de mujeres y hombres?","o":["La aprobación de leyes orgánicas en materia de violencia de género.","La ejecución de medidas de acción positiva en su ámbito territorial.","El análisis de estudios e investigaciones sobre la situación de mujeres y hombres encargados al Gobierno Vasco.","El establecimiento de medidas de fomento a fin de exigir a los ayuntamientos y demás entidades locales que dediquen recursos materiales, económicos y personales para el desarrollo de programas y actividades dirigidas a la consecución de la igualdad de mujeres y hombres."],"a":1},{"id":250,"q":"La organización de la Diputación Foral de Gipuzkoa en materia de igualdad de mujeres y hombres estará conformada por:","o":["El Órgano para la Igualdad de Mujeres y Hombres, las unidades departamentales para la igualdad de mujeres y hombres, las estructuras de coordinación interdepartamental de carácter político y de carácter técnico y las estructuras de coordinación intradepartamental de carácter político y de carácter técnico.","El Órgano para la Igualdad de Mujeres y Hombres, las unidades departamentales para la igualdad de mujeres y hombres y las estructuras de coordinación interdepartamental de carácter político y de carácter técnico.","El Órgano para la Igualdad de Mujeres y Hombres y las unidades departamentales para la igualdad de mujeres y hombres.","El Órgano para la Igualdad de Mujeres y Hombres."],"a":0},{"id":251,"q":"De acuerdo con la Norma Foral 2/2015, de 9 de marzo, ¿cuál es la configuración y el ámbito exclusivo de actuación del Órgano para la Igualdad de Mujeres y Hombres?","o":["Se configura como un organismo autónomo cuyo ámbito es la gestión de subvenciones en materia de género.","Se configura como un órgano de carácter transversal cuyo ámbito exclusivo de actuación será garantizar el impulso de las políticas forales en materia de igualdad de mujeres y hombres.","Se configura como una unidad administrativa consultiva cuyo ámbito es la inspección de las empresas privadas de Gipuzkoa.","Se configura como un departamento independiente cuyo ámbito exclusivo es la atención a víctimas de discriminación."],"a":1},{"id":252,"q":"Señale cual es una de las funciones de las unidades departamentales para la igualdad de mujeres y hombres ejercerán, en cumplimiento de los criterios y bajo la coordinación del Órgano para Igualdad de Mujeres y Hombres:","o":["Velar por la aplicación efectiva del principio de igualdad de mujeres y hombres dentro de su respectivo departamento, y en los organismos autónomos, entidades públicas empresariales y sociedades mercantiles forales en su caso adscritos al mismo.","Asistir a los órganos del su departamento y, en su caso, a los órganos de los organismos autónomos, entidades públicas empresariales y de las sociedades mercantiles forales adscritas al mismo, en la atención, prevención, actuación y eliminación de posibles situaciones de discriminación que se produzcan en el ámbito de sus organizaciones.","Diseñar e impulsar medidas específicas de acción positiva en las áreas de actuación de su departamento y en su caso, de los organismos autónomos, entidades públicas empresariales y de las sociedades mercantiles forales adscritas al mismo.","Las tres opciones anteriores son correctas."],"a":3},{"id":253,"q":"Las estructuras de coordinación y de interlocución social para la igualdad de mujeres y hombres están formados por:","o":["Estructuras de coordinación interdepartamental para la igualdad de mujeres y hombres, estructuras de coordinación intradepartamental para la igualdad de mujeres y hombres y estructuras de interlocución social para la igualdad de mujeres y hombres.","Estructuras de coordinación interdepartamental para la igualdad de mujeres y hombres y estructuras de coordinación intradepartamental para la igualdad de mujeres y hombres.","Estructuras de coordinación interdepartamental para la igualdad de mujeres y hombres y estructuras de interlocución social para la igualdad de mujeres y hombres.","Estructuras de coordinación intradepartamental para la igualdad de mujeres y hombres y estructuras de interlocución social para la igualdad de mujeres y hombres."],"a":0},{"id":254,"q":"De acuerdo con la Norma Foral 2/2015, de 9 de marzo, la Diputación Foral de Gipuzkoa garantizará la capacitación especializada en materia de igualdad de mujeres y hombres de:","o":["Todo el personal.","Los y las jefes y jefas de servicio.","Los y las jefes y jefas de servicio, los y las jefes y jefas de sección y el personal técnico de igualdad.","El personal técnico de igualdad."],"a":3},{"id":255,"q":"El órgano competente de la Diputación Foral de Gipuzkoa para el desarrollo de las políticas específicas para la igualdad de mujeres y hombres será:","o":["El Órgano para la Igualdad de Mujeres y Hombres.","La Diputada Foral de Cuidados y Políticas Sociales.","El Órgano de coordinación interdepartamental de carácter político y de carácter técnico.","El Órgano de coordinación intradepartamental de carácter político y de carácter técnico."],"a":0},{"id":256,"q":"De acuerdo con la Norma Foral 2/2015, de 9 de marzo, ¿a qué área de actuación corresponde la promoción del cambio de valores y lucha contra los prejuicios que obstaculizan la participación sociopolítica de las mujeres y otras personas transgresoras del orden heteropatriarcal?","o":["El fomento de las políticas públicas locales para la igualdad de mujeres y hombres.","Garantizar el apoyo a redes y prácticas feministas.","El desarrollo de medidas de sensibilización social, conocimiento y práctica que permitan transitar hacia un modelo de organización socio-económica en igualdad que coloque el cuidado de las personas en el centro.","Impulsar la coordinación en el diseño, seguimiento y evaluación de la política foral de lucha contra la violencia machista con el departamento de la Diputación Foral de Gipuzkoa al que se le atribuyen las funciones y competencias en materia de política social, articulada en el marco de la política foral para la igualdad de mujeres y hombres."],"a":1}];
